quests[13400] = { id = 13400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Jäger und der Prinz", description = "Bevor der Prinz König wurde, schlug er viele Schlachten... doch nur bei einer wäre er beinahe gestorben.\n\nSie fand genau hier statt. Nachdem ich Euch gezeigt habe, was hier einst geschah, werdet Ihr verstehen.\n\nSucht nach einem blutbefleckten Stein und hebt ihn auf. Ihr werdet sehen, was einst geschah.", sourceObjective = "Matthias Lehner im Hof der Knochen möchte, dass Ihr nach einem blutbefleckten Stein sucht und das Schicksal des Prinzen zu Ende bringt.", progress = "Habt Ihr es gesehen, {name}? Habt Ihr es gesehen?", completion = "Nach dem Kampf erkannte der Prinz, dass das, was ihn zurückhielt, seine Menschlichkeit war... Er konnte noch immer fühlen... konnte noch immer bluten. Er hatte noch immer ein Herz.\n\nSeine erste Handlung als König war es, sein Herz loszuwerden. Er warf es die Grube hinunter, in der wir uns zum ersten Mal begegneten. Und Ihr, {name}, wart der Erste, der es seitdem berührt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13401] = { id = 13401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist eine schreckliche Bürde", description = "Jetzt wisst Ihr, womit Ihr es zu tun habt, {name}. Ein Gegner, der keinen Schmerz mehr kennt... keine Zweifel... und auch keine Menschlichkeit. Ein Gegner, der alles tun würde, um das zu bekommen, was er will.\n\nDas Herz war seine Schwachstelle und er weiß jetzt, dass Ihr es gefunden habt.\n\nWenn Ihr zurückwollt, um es zu holen, dann nehmt Euch besser Hilfe mit. Er wird es nicht noch einmal unbewacht lassen.", sourceObjective = "Meldet Euch bei Thassarian an Bord der Himmelsbrecher.", completion = "Immer langsam, {name}. Wieso fangt Ihr nicht einfach noch mal von vorne an... von ganz vorne.", sourceObjectiveStatus = "unverified-source-field" }
quests[13402] = { id = 13402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Hilfe", description = "Es ist nicht das erste Mal, dass ich die Geschichte über Arthas und sein Herz gehört habe... habe immer gedacht, dass es eine erfundene Geschichte für gewöhnliche Soldaten wäre.\n\nWir müssen umgehend danach handeln. Leider müssen wir das Ganze geheim halten.\n\nArthas' Agenten sind überall und wenn er es herausfindet, wäre unser Plan zunichte.\n\nWir müssen dies zum Argentumkreuzzug bringen. Jeder einzelne Paladin in dem Orden wurde von Tirion höchstpersönlich erlesen. Wenn irgendwer noch nicht von den Kultisten infiltriert wurde, dann sind es diese Jungs.", sourceObjective = "Sprecht mit Hochlord Tirion Fordring auf dem Kreuzfahrerturm.", completion = "Harte Worte, {name}. Hätte jemand anderes das gesagt, hätte ich ihn wahrscheinlich für verrückt erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13403] = { id = 13403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tirions Schachzug", description = "Diesen Morgen haben mich meine Späher darüber informiert, dass eine Prozession des Kults der Verdammten mit einem Artefakt von der Eiskronenzitadelle in Richtung Kathedrale der Dunkelheit aufgebrochen ist.\n\nUnd nun wird mir gesagt, dass es sich hierbei um Arthas' eigenes Herz handelt... ein Gegenstand, der den letzten Rest seiner Menschlichkeit enthält.\n\nDies ist ein Zeichen des Lichts. Solange solch ein Artefakt existiert, besteht eine Chance, dass Arthas Menethil wieder ein Mensch werden kann!\n\nTrefft mich am Eingang der Kathedrale. Bringt auf jeden Fall eine Kultistenverkleidung mit - wir gehen inkognito.", sourceObjective = "Tirion Fordring auf dem Kreuzfahrerturm möchte, dass Ihr die Kultistenkapuze besorgt, diese anzieht und Euch mit ihm am Eingang zur Kathedrale der Dunkelheit nordwestlich der Eiskronenzitadelle trefft.", completion = "Ich betrachte das, was wir soeben durchgemacht haben, nicht als Fehlschlag, {name}... im Gegenteil.\n\nDadurch, dass ich einen Blick in sein Herz werfen konnte, habt Ihr mir erlaubt, das zu bestätigen, was ich wissen musste. Es gibt keinen Arthas Menethil mehr - nur noch den Lichkönig.", sourceObjectiveStatus = "unverified-source-field" }
quests[13404] = { id = 13404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Statische Schocktruppen: das Bombardement", description = "Dies wird ein Kurzstreckeneinsatz, über das Bombardement. Gut zum warm werden. Bereit?", sourceObjective = "Kibli Killohertz möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementkapitäne und 20 Gargoylewegelagerer tötet.", progress = "Bleibt dran, {name}. Der Luftkrieg gewinnt sich nicht von selbst!", completion = "Willkommen zurück, {name}. Eine kurze Mission, aber belebend, was? Macht erstmal 'ne Pause. Aber kommt zurück, sobald Ihr neue Befehle habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13405] = { id = 13405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Strand der Uralten", description = "Wir kämpfen in Nordend nicht nur gegen die Armeen des Lichkönigs, sondern auch gegen die Armeen der Horde.\n\nAuf dem Strand der Uralten wurde ein mächtiges Titanenrelikt gefunden. Wie Ihr vielleicht schon wisst, sind wir Zwerge seit Jahren Hüter solcher Artefakte gewesen und sind deswegen auch ihre rechtmäßigen Besitzer.\n\nIn diesem Fall ist die Horde sehr scharf darauf, das Relikt aus den Titanenruinen zu klauen. Sie werden es sicherlich als Waffe gegen uns einsetzen - wir müssen sie also um jeden Preis aufhalten.", sourceObjective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Ausgezeichnete Arbeit, {name}! Mit Eurer Hilfe wird der komplette Strand der Uralten der Allianz zufallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13406] = { id = 13406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf derselben Wellenlänge: Das Bombardement", description = "Bereit, Euch mit einer kurzen Bombenmission aufzuwärmen? Ihr habt Eure Befehle und wir unsere Bomber - bestückt und bereit.", sourceObjective = "Grenzwissenschaftsingenieurin Tezzla möchte, dass Ihr 50 Bombardementinfanteristen, 10 Bombardementhauptmänner und 20 Gargoylewegelagerer tötet.", progress = "Ihr habt Eure Trefferquote noch nicht erfüllt, {name}. Los, raus da mit Euch und jagt etwas in die Luft!", completion = "Ha, Ihr habt sie erwischt! Ich konnte hören, wie einzelnen Körperteile der Geißel die Bergwand herunterrasselten. Gute Arbeit. Wir werden schon bald noch mehr für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13407] = { id = 13407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Strand der Uralten", description = "Nur weil wir in Nordend einmarschieren, um die Geißel zu vernichten, muss das noch lange nicht heißen, dass wir der Allianz eine Pause gönnen.\n\nDie Zwerge von der Forscherliga haben ein mächtiges Titanenrelikt gefunden und der Blitz soll uns treffen, wenn wir es einfach der Allianz überlassen.\n\nGeht, {name}, und vernichtet unsere Feinde. Sie sollen wissen, dass, egal wo wir uns auch begegnen, sie weiterhin unsere Todfeinde sind.", sourceObjective = "Gewinnt eine Schlacht auf dem Strand der Uralten und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, in Tausendwinter, Dalaran oder Shattrath.", completion = "Ihr macht uns große Ehre, {name}! Die Schwächlinge der Allianz müssen unter dem Stiefel der mächtigen Horde zerquetscht werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[13408] = { id = 13408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13409] = { id = 13409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13410] = { id = 13410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenfeuerzitadelle steht im ständigen Kampf mit unseren Streitmächten. Wir halten uns wacker, aber wir können keinen richtigen Angriff gegen sie starten. Um dies zu tun, müssen wir weiter vorrücken.\n\nUnsere Späher haben drei Befestigungsanlagen in der Nähe der Höllenfeuerzitadelle entdeckt. Wir möchten, dass Ihr uns helft, diese drei Anlagen einzunehmen. Meldet Euch bei mir, sobald Ihr eine in Beschlag nehmen konntet.\n\nMöge das Glück in den vor Euch liegenden Kämpfen bei Euch sein, {name}, denn Ihr werdet ohne Zweifel auf Streitkräfte der Horde treffen, die dasselbe im Schilde führen.", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Stabsfeldwebel Tracy Stolzbrunn in der Ehrenfeste auf der Höllenfeuerhalbinsel zurück.", completion = "Gut gemacht, {name}. Eure Taten auf dem Schlachtfeld sind für unseren Kampf auf der Höllenfeuerhalbinsel sehr hilfreich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13411] = { id = 13411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerbefestigungen", description = "Die Höllenorcs der Höllenfeuerzitadelle müssen von unserem Heimatland entfernt werden! Um sie anzugreifen, müssen wir strategisch wichtige Punkte in der Nähe der Zitadelle einnehmen.\n\nUnsere Kundschafter haben drei Befestigungsanlagen ausgemacht, die für unsere Zwecke geeignet sind, aber die Allianz hatte dieselbe Idee und schickt schon Streitkräfte, um sie einzunehmen!\n\nWir möchten, dass Ihr die Allianz aufhaltet und die drei Forts einnehmt. Helft bei der Einnahme jeder Anlage und kehrt dann zu mir zurück.\n\nFür die Horde!", sourceObjective = "Nehmt den Rundblick, das Stadion und die Trümmerbastion ein, und kehrt dann zu Kriegsherold Blauauge in Thrallmar zurück.", progress = "Kehrt zu mir zurück, wenn Ihr bei der Einnahme der Befestigungsanlagen geholfen habt!", completion = "Gute Arbeit, {name}. Ich konnte fast die Kampfschreie an den Befestigungsanlagen hören. Ich wünschte, ich wäre dabei gewesen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13412] = { id = 13412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corastrasza", description = "Grüße, {class}. Dürfte ich Euch um einen Gefallen bitten?\n\nCorastrasza ist die Schwester von Raelorasz - dem roten Drachen, der hier in unserem Außenposten das Sagen hat. Sie ist gegen seinen Willen zu einem der oberen Nexusringe geflogen, um ein paar blaue Drachen, die über fürchterliche Macht verfügen, zu beobachten.\n\nEr macht sich um sie Sorgen, obwohl er es nie zugeben wird, und würde jegliche Neuigkeiten über ihr Wohlergehen begrüßen.\n\nSeid so gut und sucht sie auf. Bittet sie, ihren Stolz beiseite zu legen und ihrem Bruder eine Nachricht zu schicken.", sourceObjective = "Bibliothekarin Serrah möchte, dass Ihr mit Corastrasza in Kaltarra sprecht.", completion = "Es ist ziemlich anmaßend, Euch in die persönlichen Angelegenheiten eines Drachen einzumischen, meint Ihr nicht, {race}?\n\nDoch abgesehen davon, wäre es nicht richtig, meinem Bruder vorzuenthalten, dass es mir gut geht. Ihr könnt Eurer aufdringlichen Freundin sagen, dass ich meinen Bruder über das, was ich mache, auf dem Laufenden halten werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13413] = { id = 13413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "Ihr besitzt den Mut, Euch so nah an Malygos' Hort heranzuwagen, <Sterblicher/Sterbliche>? Oder ist es einfach nur Ignoranz? Bald werden wir es wissen...\n\nIch bin ein erfahrener Ausbilder der anmutigen Drachen des roten Drachenschwarms. Meine Aufgabe hier ist es, den Feind zu studieren und meinen kostbaren Begleitern die Taktiken beizubringen, die sich am effektivsten gegen den Meister der Blauen erweisen werden.\n\nDamit Ihr zeigen könnt, ob Ihr die Nerven und das Können besitzt, werde ich Euch erlauben, auf einem meiner Drachen in den Kampf gegen die Untergebenen des Feindes zu reiten.\n\nDie Möglichkeit besteht - Ihr müsst nur danach fragen...", sourceObjective = "Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", progress = "Tja, Sterblicher, was haltet Ihr von meinen Begleitern?", completion = "Mein Drache sagt mir, dass Ihr es mit ein wenig Übung zu einem fähigen Kämpfer machen könntet.\n\nNun gut. Im Interesse unseres Krieges mit Malygos werde ich Euch erlauben, nach Belieben mit einem meiner Begleiter zu trainieren.\n\nBereitet Euch vor, {race}, denn er ist ein heftiger und gnadenloser Gegner.", sourceObjectiveStatus = "unverified-source-field" }
quests[13414] = { id = 13414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "So sehen wir uns wieder, {race}. Ich muss zugeben, dass Ihr mir langsam ans Herz wachst.\n\nLiege ich richtig in der Annahme, dass Ihr gekommen seid, um Eure Luftkampffertigkeiten zu verbessern?\n\nMeine Begleiter stehen wie immer bereit, Ihr zerstörerisches Feuer über den Feind zu ergießen.\n\nSprecht nur ein Wort und sie werden Euch zur Verfügung stehen.", sourceObjective = "Corastrasza auf dem oberen Ring des Nexus in Kaltarra möchte, dass Ihr auf ihrem Drachen 5 Elitesoldaten der Eidschuppen tötet.", progress = "Ja, {race}?", completion = "Ich habe heute eine leichte Steigerung bemerkt, {class}. Es gab Momente, in denen es so schien, als wäret Ihr eins mit dem Drachen.\n\nIhr könnt gerne nach Eurem Belieben mit meinen kostbaren Begleitern trainieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13415] = { id = 13415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bibliothekenkonsole", description = "Norgannons Schale liegt in Reichweite, {name}. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe dazu benutzen, um die Schale zu besorgen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", sourceObjective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "<Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:>\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13416] = { id = 13416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bibliothekenkonsole", description = "Norgannons Schale liegt in Reichweite, {name}. Bringt die Scheibe des Erfinders ins Innere der Bücherei. Dort sollte sich eine Konsole befinden, die Ihr mithilfe der Scheibe aktivieren könnt. Ich kann mir vorstellen, dass Mimir dort mehr als nur Norgannons Schale versteckt hat. Es befinden sich wahrscheinlich genug Schemata dort, um die Ingenieure von Eisenschmiede über Jahre hinweg zu beschäftigen!\n\nJedenfalls sollt Ihr die Scheibe zur Konsole bringen. Hoffentlich hat Mimir sich nicht dazu entschlossen, noch mehr Hindernisse in Euren Weg zu stellen.", sourceObjective = "Bringt die Scheibe des Erfinders zur Bibliothekenkonsole des Erfinders im Inneren der Bibliothek des Erfinders.", progress = "Auf der Konsole befindet sich eine Öffnung, die anscheinend für die Scheibe des Erfinders gedacht ist.", completion = "<Ihr schiebt die Scheibe in die Konsole. Plötzlich erscheinen Lichter auf deren Oberfläche und eine mechanische Stimme sagt:>\n\nScheibe des Erfinders bestätigt. Willkommen zurück, Hüter Mimir.", sourceObjectiveStatus = "unverified-source-field" }
quests[13417] = { id = 13417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Bronzebart", description = "Das war's! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen diesem Ding war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.\n\nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!", sourceObjective = "Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13418] = { id = 13418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitung", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nIhr habt vielleicht die Gerüchte über unseren fehlgeschlagenen Bodenangriff auf den Gletscher gehört, doch lasst mich Euch beruhigen. Wir führen unseren Angriff jetzt von einem der fortgeschrittensten Gefährte aus, die es in Azeroth gibt: die Himmelsbrecher. Die Horde hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen.", sourceObjective = "Sprecht mit Offizier Van Rossem, um Euch sicher zur Himmelsbrecher in Eiskrone bringen zu lassen, und meldet Euch dann bei Stabshauptmann Justin Bartlett.", completion = "Willkommen auf der Himmelsbrecher.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Absalan dem Frommen auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13419] = { id = 13419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorbereitung", description = "Ihr da!\n\nIhr seht aus, als hättet Ihr etwas auf dem Kasten. Wir könnten ein paar fähigere Leute in Eiskrone gebrauchen.\n\nDie Hunde von der Allianz sind vor uns nach Eiskrone geeilt, unvorbereitet, und haben für ihre Ungeduld genau das bekommen, was sie verdienen. Wir haben uns Zeit gelassen, haben uns vorbereitet und schon bald werden wir den echten Angriff starten - von einem der fortgeschrittensten Gefährte in ganz Azeroth aus: der Orgrims Hammer. Die Allianz hat keine Chance und auch Arthas nicht.\n\nSagt mir Bescheid, wenn Ihr bereit seid, aufzubrechen und zu helfen.", sourceObjective = "Sprecht mit Himmelshäscher Klum, um Euch sicher zur Orgrims Hammer in Eiskrone bringen zu lassen, und meldet Euch dann bei Himmelshäscher Korm Schwarznarbe.", completion = "Willkommen auf der Orgrims Hammer.\n\nVon hier aus werden wir die Vorarbeit für unseren Angriff auf Arthas leisten. Es gibt noch viel zu tun, doch bevor wir uns ins eigentliche Getümmel stürzen können, wollen wir sichergehen, dass der Argentumkreuzzug ausreichend Verstärkung erhalten hat - wir werden später ihre Hilfe benötigen.\n\nSprecht mit Bruder Keltan auf dem Hauptdeck, wenn Ihr das nicht schon getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13420] = { id = 13420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immerfrost", description = "Dieses Stück Eis war enormen Kräften und natürlicher Magie aus den Tiefen der Erde ausgesetzt. Zusammen haben diese Effekte ein Eis geschaffen, das niemals schmelzen wird.\n\nDa Ihr Euch in solchen Dingen nur wenig auskennt, entschließt Ihr Euch, die Probe zurück nach Dun Niffelem zu bringen. Dort muss es irgendjemanden geben, der mit dessen Eigenschaften vertraut ist.", sourceObjective = "Ihr müsst nach Dun Niffelem zurückkehren und Euch bei Calder über das Stück Immerfrost erkundigen.\n\nBereitgestellter Gegenstand:", completion = "<Das Licht des Immerfrosteises leuchtet in Calders Augen, als er es hochhält.>\n\nAhh, Immerfrost - Symbol des Herzens meines Volkes...\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13421] = { id = 13421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst das Immerfrosteis nicht!", progress = "Habt Ihr noch mehr Immerfrost gefunden, kleiner {race}?", completion = "Gut gemacht, kleiner {class}.\n\nImmerfrost gab es einst in dieser Region in Hülle und Fülle. Doch im Laufe der Zeit haben die Jormungar beinahe alles verschlungen. Heute ist es sehr selten und äußerst wertvoll für mein Volk.\n\nHaltet auf Euren Reisen durch dieses Land nach noch mehr Stücken Immerfrosts Ausschau. Bringt mir alles, was Ihr finden könnt, und wir werden überaus dankbar sein." }
quests[13422] = { id = 13422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin bewahren", description = "Ihr habt das geschafft, woran andere gescheitert sind. Doch auf Euren Lorbeeren könnt Ihr Euch noch nicht ausruhen.\n\nIhr müsst anderen zeigen, was Stärke und Engagement wirklich bedeuten.\n\nDie Aufsässigen in der verlorenen Mine müssen wieder einmal diszipliniert werden. Zeigt es ihnen, Schwester... zeigt ihnen, was es bedeutet, uns nicht zu gehorchen.", sourceObjective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul in der Verlassenen Mine anwendet.", completion = "Ihr geht weiterhin mit gutem Beispiel voran. Wir sehen zu Euch auf, Schwester.", sourceObjectiveStatus = "unverified-source-field" }
quests[13423] = { id = 13423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euren Titel verteidigen", description = "Alle sind von Eurer Leistung beeindruckt, Schwester. Doch lasst Eure Deckung nicht sinken. Jeder neue größenwahnsinnige Herausforderer wird jetzt herauskommen und sich Euren Titel als Hyldskvinnar schnappen wollen.\n\nZeigt diesen Emporkömmlingen, aus welchem Holz Ihr geschnitzt seid.", sourceObjective = "Gretta die Schiedsfrau in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.", progress = "Wir verbeugen uns vor Eurer Kraft, Schwester.", completion = "Ihr erweist Euch weiterhin als würdig. Eure Anwesenheit ehrt uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[13424] = { id = 13424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Grube", description = "Um auch weiterhin wirklich gut reiten zu können, werdet Ihr Euch jeden Tag gegen die Hyldnir beweisen müssen.\n\nBegebt Euch zurück zur Reißzahngrube und zeigt ihnen, wozu Ihr fähig seid. Sie werden dankbar sein, gegen jemanden zu verlieren, der so geschickt ist wie Ihr.", sourceObjective = "Gretta die Schiedsfrau aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Eisschlundmatriarchin 6 Kriegsbären des Hildarthings besiegt.", completion = "Ihr beweist auch weiterhin, was Ihr könnt. Eure Schwestern respektieren Euch noch immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[13425] = { id = 13425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Missgeburten müssen sterben", description = "Euer Können unter Euresgleichen zu beweisen, ist nicht genug. Ihr müsst auch gegen unsere Feinde kämpfen, liebe Schwester.\n\nDie Valkyrionverräter verhöhnen weiterhin unsere edlen Drachenreittraditionen, indem sie verseuchte Protodrachen großziehen.\n\nKommt in den Besitz ihres Frostöls, das sie bei sich tragen, und benutzt es, um ihre widerwärtigen verseuchten Eier einzufrieren.", sourceObjective = "Gretta die Schiedsfrau in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", completion = "Ihr seid in mehr als nur einer Hinsicht eine Anführerin. Wir danken Euch, Schwester.", sourceObjectiveStatus = "unverified-source-field" }
quests[13426] = { id = 13426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeuge Xarantaur", description = "Scheint, als wären wir nicht die einzigen Besucher dieser Gegend. Ein Kurier hat eine Nachricht von einem Tauren namens Xarantaur weitergeleitet, der gemeint hat, er habe ein Taunkadorf namens Camp Tunka'lo besucht. Der Zettel war zwar etwas kryptisch geschrieben, doch es scheint, als sei dieser Xarantaur in die Sturmgipfel gegangen, um der Geschichte einer Taunkalegende nachzugehen.\n\nTrefft Euch mit ihm, {name}. Seht nach, ob das, was er weiß, uns in irgendeiner Art und Weise behilflich sein kann. Seiner Beschreibung nach befindet sich Camp Tunka'lo weit gen Osten, jenseits der Terrasse der Schöpfer und nördlich von Dun Niffelem.", sourceObjective = "Sprecht mit Xarantaur im Camp Tunka'lo.", completion = "Boktar hat also meine Nachricht erhalten? Das sind ausgezeichnete Neuigkeiten. Ich habe bezweifelt, ob der Träger, ein Fernläufer der Taunka, überhaupt irgendjemanden erreichen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13427] = { id = 13427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Wenn man an mehreren Fronten gleichzeitig kämpft, kann man es sich nicht leisten, seine Streitkräfte zu weit zu verstreuen oder man riskiert, alles zu verlieren!\n\nKritische Entscheidungen über die Stationierung unserer Streitkräfte müssen jeden Tag aufs Neue getroffen werden. Heute ist es die Schlacht im Alteractal, in der wir unsere Streitkräfte dringend verstärken müssen.\n\nGeht, {name}, und unterstützt die Expeditionsstreitkräfte des Sturmlanzenklans. Nach allem, was unseren Brüdern und Schwestern angetan wurde, dürfen wir den Frostwolfklan nicht so einfach davonkommen lassen.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Genau das wollte ich hören! Ein Sieg im Alteractal, auch wenn er nur vorübergehend ist, wird uns den weiteren Kampf gegen die Horde enorm erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13428] = { id = 13428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf zu den Waffen: Alteractal", description = "Es scheint, als stünden wir kurz davor, die Sturmlanzeninvasoren aus dem Alteractal zu vertreiben. Momentan verlegen wir all unsere Verstärkungstruppen ins Tal, um die Frostwölfe in ihrem Kampf zu unterstützen.\n\nEin vollständiger Sieg im Alteractal würde uns genug Freiraum verschaffen, um mit den freigewordenen Truppen den Allianzabschaum auch an anderen Fronten zu schlagen.\n\nGeht nun, {name}. Ehrt Euch selbst und folgt dem Schlachtruf der kühnen Frostwolfkrieger.", sourceObjective = "Gewinnt eine Schlacht im Alteractal und meldet Euch anschließend bei einem Kriegshetzer der Horde in einer der Hauptstädte, Tausendwinter, in Dalaran oder Shattrath.", completion = "Es gibt nichts Ehrenvolleres, als die feindlichen Invasoren aus dem Gebiet der Horde zu vertreiben. Ich verneige mich vor Eurem Mut und danke Euch dafür, dass Ihr unseren Streitkräften heute einen großen Dienst erwiesen habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13429] = { id = 13429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ablenkungsmanöver für Akama", description = "<Licht pulsiert um Xi'ri herum während die Streitkräfte der Aldor und der Seher seine Befehle ausführen. Xi'ris Armee ist bereit, Illidans Streitkräfte zurückzudrängen und Akama das nötige Ablenkungsmanöver zu verschaffen. Der Naaru wartet auf Eure Aufforderung den Angriff durchzuführen.>", sourceObjective = "Stellt sicher, dass Akama und Maiev den Schwarzen Tempel betreten, nachdem Xi'ris Streitkräfte ihr Ablenkungsmanöver durchgeführt haben.", completion = "<Xi'ri pulsiert vor Energie, Ihr fühlt, wie ein Gegenstand in Euren Händen Gestalt annimmt. Es ist das Medaillon, das Ihr A'dal im Namen von Akama gegeben habt. Seine Macht hat sich durch die Magie der Naaru noch verstärkt. Die Sha'tar haben Euch das Medaillon von Karabor anvertraut, und damit den Zugang zum Schwarzen Tempel.>", sourceObjectiveStatus = "unverified-source-field" }
quests[13430] = { id = 13430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Naaru: Magtheridon", description = "Ihr müsst vier Prüfungen bestehen, bevor Ihr von den Naaru als würdig genug erachtet werdet.\n\nEs bleibt nur noch eine übrig, <Sterblicher/Sterbliche>. Sammelt eine Armee und reist zu Magtheridons Kammer tief in der Höllenfeuerzitadelle. Kämpft Euch bis zur Mitte der Kammer durch und vernichtet diesen miesen Verderber!", sourceObjective = "A'dal in Shattrath möchte, dass Ihr Magtheridon vernichtet.", completion = "Ihr habt Euch als Wesen mit großer Macht bewiesen. Die Naaru sind sich einig...", sourceObjectiveStatus = "unverified-source-field" }
quests[13431] = { id = 13431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Knüppel von Kar'desh", description = "Bringt mir die Elementarsiegel, die ich für den Knüppel brauche!\n\nDas Erdensiegel befindet sich im Besitz von Gruul dem Drachenschlächter. Ihr findet ihn in seinem Unterschlupf im Schergrat.\n\nDas zweite Siegel ist das flammende Herz einer Kreatur, die als Schrecken der Nacht bekannt ist. Diese mystische Kreatur soll sich angeblich in den geheiligten Hallen des Propheten Medivh aufhalten.\n\nBeeilt Euch!", sourceObjective = "Nar'biss der Ketzer in den heroischen Sklavenunterkünften des Echsenkessels möchte, dass Ihr ihm das Erdensiegel und das Flammensiegel bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13432] = { id = 13432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Phiolen der Ewigkeit", description = "Illidan entnahm sieben Phiolen aus dem Brunnen der Ewigkeit. Drei davon leerte er in den See auf dem Berg Hyjal, wodurch ein zweiter Brunnen der Ewigkeit entstand. Jahrelang glaubte man den Rest verloren.\n\nSeit der Öffnung des Dunklen Portals haben wir erfahren, dass er seinen Leutnants Kael'thas und Vashj je eine Phiole gegeben hat. Holt zurück, was von den Phiolen noch übrig ist. Wir brauchen sie als Fokus, um ein Tor zu den Geschehnissen, seien sie aktuell oder vergangen, am Berg Hyjal zu öffnen. Das Ergebnis der Schlacht um den Berg Hyjal muss erhalten bleiben.", sourceObjective = "Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt.", sourceObjectiveStatus = "unverified-source-field" }
