quests[13501] = { id = 13501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13502] = { id = 13502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenverkäufer möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokoladen wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13503] = { id = 13503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Korb bekommen!", description = "Hier... nehmt diesen Eierkorb und geht nach bunt gefärbten Eiern suchen. Kehrt zu mir zurück, sobald Ihr zehn Nobelgartenschokoladen gesammelt habt.", sourceObjective = "Der Nobelgartenhändler möchte, dass Ihr 10 Nobelgartenschokoladen sammelt und ihm zusammen mit dem Eierkorb zurückbringt.", progress = "Habt Ihr die zehn Nobelgartenschokoladen?", completion = "Gut gemacht! Und hier, bitte... behaltet den Korb!\n\nUnd denkt dran, Ihr könnt jederzeit mit mehr Nobelgartenschokolade wiederkommen, um sie gegen weitere Gegenstände einzutauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13504] = { id = 13504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiter der Splitterspeere", description = "In den Ruinen im Norden und Nordosten gibt es eine große Schar von Splitterspeertrollen, die dort herumstöbern. Ich vermute, sie suchen nach magischen Artefakten, aber keiner unserer Späher kann von nennenswerten Funden in ihren Ausgrabungsstätten berichten. Vielleicht treiben sie ja auch einfach nur ihre Kriegsmaschinerie voran.\n\nEines ist aber recht sicher: Arbeitermangel würde ihren Angriff schwächen, also verpassen wir ihnen einen Arbeitermangel. Seid Ihr dabei?", sourceObjective = "Tötet 10 Arbeiter der Splitterspeere.", completion = "Gute Arbeit. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13505] = { id = 13505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Hochgeborenen", description = "Es gibt überall an der Dunkelküste ähnliche Ruinen wie diese und viele von ihnen werden von geplagten Geistern der Hochgeborenen heimgesucht. Aus Rücksicht auf ihre verfluchten Seelen haben wir uns bisher damit zurückgehalten, die Ruinen nach Artefakten zu durchsuchen, aber solche guten Vorsätze müssen im Angesicht dieser neuen Bedrohung durch die Trolle aufgegeben werden.\n\nBitte bergt sämtliche Artefakte, auf die Ihr stoßt, während Ihr den Schildwachen bei der Erfüllung ihrer Ziele in den Ruinen helft, und bringt sie zu mir zurück. Ich würde gern so viele retten, wie ich kann.", sourceObjective = "Erhaltet 8 Hochgeborenenrelikte.", progress = "Konntet Ihr irgendwelche Artefakte bergen?", completion = "Perfekt! Habt vielen Dank. Ich würde nur sehr ungern noch mehr Zeugnisse unserer Kultur an den Krieg verlieren - viel zu Vieles mussten wir schon opfern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13506] = { id = 13506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grund zur Sorge", description = "Hierbei scheint es sich um Befehle zu handeln, die von einem Vorgesetzten im Kriegslager der Splitterspeere an die Vorarbeiter in den Ruinen geschickt wurden. Der Großteil der Dokumente ist von unwesentlichem strategischen Wert, aber ein paar Zeilen fallen Euch auf.\n\n\"Wir haben noch eine Nachtelfenspionin aufgegriffen. Sie wurde zum Lager gebracht, um ihr unter Folter mehr Informationen zu entlocken. Haltet nach weiteren Spionen Ausschau - wir können es uns nicht leisten, dass unsere Operation hier aufgedeckt wird.\"\n\nLeutnant Sternenhauch möchte diese Informationen sicher sehen.", sourceObjective = "Bringt die Splitterspeerbefehle zu Leutnant Morra Sternenhauch in den Ruinen von Mathystra.", progress = "Ja, {class}?", completion = "\"Noch einen\"? Sie haben also mehr als einen. Ich werde keinen meiner Leute der Folter überlassen, wir müssen schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[13507] = { id = 13507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwehrt ihnen die Arbeit", description = "Im Norden haben die Splitterspeere ein Kriegslager, in dem sie ihre Katapulte bauen. Das Lager wird von einigen ihrer Mystiker bewacht, aber ich habe auch erste Berichte erhalten, dass Orcs und Tauren ebenfalls gesichtet wurden.\n\nIch möchte keine Spekulationen anstellen, was das bedeuten könnte, aber ich möchte sehr wohl, dass Ihr Euch auf den Weg macht und sie tötet, bevor sie noch weitere Angriffe auf unsere Schildwachen starten können.", sourceObjective = "Tötet 6 Vollstrecker der Horde und 6 Mystiker der Splitterspeere.", completion = "Ausgezeichnete Arbeit. Eine weitere Bedrohung, über die wir uns etwas weniger Sorgen machen müssen. Wir werden unseren Angriff fortsetzen, während sie noch desorientiert sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13508] = { id = 13508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelle Reaktion", description = "Wir haben vor ein paar Tagen den Kontakt mit einer meiner Späherinnen verloren. Ich hielt sie für tot, aber anscheinend wurde sie nur gefangen genommen. Den Trollen nach haben sie aber zwei Gefangene... Die einzige weitere Person, die in Frage kommt, ist Alanndarian Nachtweise, eine Zivilistin, die sich gestern Vormittag gegen meinen Rat in der Gegend aufgehalten hat.\n\nDie Splitterspeere haben im Norden ein Kriegslager aufgeschlagen - dorthin werden sie mit an Sicherheit grenzender Wahrscheinlichkeit alle Gefangenen gebracht haben. Macht sie ausfindig und befreit sie, wenn Ihr könnt.", sourceObjective = "Findet die gefangenen Nachtelfen im Kriegslager der Splitterspeere.", completion = "<Alanndarian sieht äußerst blass aus, doch schwache Atemzüge bezeugen, dass noch Leben in ihr steckt.>\n\nIhr seid hier, um... mich zu retten? Etwas später... als ich gehofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13509] = { id = 13509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsvorräte", description = "Die Trolle sammeln ihre Truppen und Vorräte in ihrem Kriegslager im Norden. Sie werden von dort fast mit Sicherheit ihren Angriff auf Lor'danel starten, sobald sie sich bereit fühlen. Es sollte nicht lange dauern, dieses Gesindel in die Flucht zu schlagen, ich bin jedoch dagegen, unnötige Risiken einzugehen.\n\nIch möchte, dass Ihr Euch einen Weg in das Kriegslager erkämpft und alle Vorräte in Brand steckt, die Ihr finden könnt. Dieser Rückschlag sollte uns einige Zeit verschaffen, bis sie einen Gegenangriff starten können.", sourceObjective = "Zerstört 12 Vorratskisten der Splitterspeere.", completion = "Ausgezeichnete Arbeit. Das sollte sie ein wenig aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13510] = { id = 13510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rechtzeitige Ankunft", description = "Schön Euch zu sehen. Ich habe mich nicht darauf gefreut, das Gleiche durchzumachen wie Alanndarian, also ist mir Eure Rettung sehr willkommen.\n\nIch konnte den Anführer der Trolle entdecken, bevor man mich fasste. Ich dachte, ich hätte die perfekte Gelegenheit, ihn auszuschalten, aber er wird von einer Art magischem Schild geschützt. Morra muss davon in Kenntnis gesetzt werden, bevor sie ihren Angriff startet, aber zuerst müssen wir hier verschwinden.\n\nHelft mir zum Dock - ich werde Lor'danel über den Wasserweg erreichen und Ihr könnt die Informationen zu Morra zurückbringen.", sourceObjective = "Bringt Schildwache Aynasha in Sicherheit.", completion = "Eine Art Schild, sagt Ihr? Dagegen haben wir vielleicht ein Mittel. Balthule ist ein Einfall gekommen, wie man jegliche Schutzzauber ihrer Schamanen durchbrechen kann. Vielleicht funktioniert das auch damit. Danke, dass Ihr Aynasha gerettet und mir diese Informationen überliefert habt - das könnte womöglich unseren Kampf hier entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13511] = { id = 13511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verbitterter Wunsch", description = "Morra schickt Euch? Ich hätte auf sie hören sollen - es ist wohl zu einfach, Trolle nicht ernst zu nehmen.\n\n<Alanndarian lacht leise in sich hinein.>\n\nDafür ist es jetzt ohnehin viel zu spät. Wir sind jetzt sterblich... dies ist das Schicksal, dem wir früher oder später erliegen werden. Ich habe Zeit genug gehabt, mich damit abzufinden.\n\nEine Bitte habe ich jedoch... tötet den Folterer, der mir das hier angetan hat. Sie nennen ihn Rit'ko... Ihr könnt ihn weiter vorne bei der anderen Gefangenen finden.\n\n<Alanndarian lächelt schwach, zuckt dann vor Schmerz zusammen und sinkt wieder zu Boden.>", sourceObjective = "Tötet Rit'ko, den Folterer der Splitterspeere.", completion = "Alanndarian ist also tot. Das bedrückt mich sehr, kommt aber nicht gänzlich unerwartet. Ich erwarte von diesen Wilden keine Gnade und werde ihnen auch keine zuteilwerden lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13512] = { id = 13512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategische Schläge", description = "Der Bestie den Kopf abzuschlagen hat keinen Sinn, wenn es einen zweiten Kopf gibt, der ihn ersetzen kann. Bevor wir ihren Anführer ausschalten können, müssen wir die Unteranführer töten, die das Machtvakuum füllen würden. Momentan werden sie nicht so gut beschützt und Ihr solltet sie ohne weitere Unterstützung besiegen können.\n\nNehmt diesen Dryadenspeer und spürt sie auf. Das Gift an seiner Spitze sollte ihre Zaubersprüche verlangsamen. Meine Späher berichten mir, dass einer von ihnen in der Wasserkammer in den Ruinen im Osten ist und der andere wurde hinter den Überresten des Turmes im Südwesten gesichtet.", sourceObjective = "Tötet Sheya Sturmwirker und Lorenth Donnerruf.", completion = "Ihr habt eine Menge Talent bewiesen für jemanden, der noch so jung ist. Gute Arbeit. Offenbar steht uns die letzte Schlacht kurz bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13513] = { id = 13513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Zurück", description = "Ich arbeite bereits an einem Mittel, um ihre Schutzzauber zu überwinden. Mit einem Fokus, der auf ihren Mächten beruht, und etwas Druidenmagie sollten wir in der Lage sein, ihre Schilde zu durchbrechen.\n\nSpürt ihre Schamanen im Osten und Südosten auf und beschafft einige ihrer Amulette. Ich werde sie vorbereiten und einen Pfeil verzaubern, den Ihr Sandrya Mondsturz für den Angriff überbringen könnt.", sourceObjective = "Erhaltet 6 Amulette der Splitterspeere.", progress = "Habt Ihr die Amulette bei Euch?", completion = "Diese Amulette sind genau das, was ich brauche. Ich werde sie für Sandrya vorbereiten - man wird Euch sicher gleich beauftragen, Euch mit ihr zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13514] = { id = 13514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn der Urtume", description = "Seid Ihr hier, um Euch dem Angriff anzuschließen? Wenn Ihr nach Sandrya Mondsturz sucht, findet Ihr sie in der Höhle am Ende dieses Tals, wo sie den Angriff auf den Anführer der Splitterspeere leitet.\n\nWo Ihr schon hier seid, könnten wir allerdings auch Eure Hilfe beim Zusammentreiben des restlichen Stammes brauchen. Zieht mit einem der rachsüchtigen Beschützer los und sorgt dafür, dass auch das letzte Gebäude zerstört und der Stamm bis auf den letzten Troll ausgelöscht wird. Wir wollen doch nicht, dass sie versuchen, sich an uns zu rächen, wenn wir nicht darauf gefasst sind, oder?", sourceObjective = "Benutzt einen rachsüchtigen Beschützer um 30 Trolle der Splitterspeere zu töten und 6 Gebäude der Splitterspeere zu zerstören.", completion = "Ihr habt Euch dort oben hervorragend geschlagen! Wir können von Glück reden, Euch bei uns zu haben.\n\nIch habe noch keine Nachricht über ihren Anführer erhalten. Wenn Ihr noch nicht mit Sandrya in der Höhle am Ende des Tals gesprochen habt, solltet Ihr das unbedingt nachholen, bevor Ihr wieder aufbrecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13515] = { id = 13515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Bedrohung", description = "Auf uns warten ihr Anführer und seine Leibwache. Meine Schildwachen sind bereit, seine Leibwächter auszuschalten. Wir warten nur auf diesen Pfeil, um das Schicksal ihres Anführers zu besiegeln.\n\nLasst es mich wissen, wenn Ihr bereit für den Angriff seid. Sobald meine Schildwachen die Höhle stürmen, werde ich den Schild des Anführers zertrümmern und wir werden ihm gemeinsam entgegentreten. Schlagt geschwind zu und wir können diese Bedrohung für unsere Ländereien hier und heute beenden.\n\nWir warten nur auf Euch - sprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Sandrya Mondsturz, um den Angriff zu starten, und helft ihr dann dabei, Jor'kil den Seelenreißer zu töten.", completion = "Wir stehen tief in Eurer Schuld für alles, was Ihr getan habt, um diese Schlacht zu einem glücklichen Ende zu bringen.\n\nEs geschieht nicht oft, dass wir einen derartig eindeutigen Sieg davontragen können, aber wie es scheint, steht hinter dieser Verschwörung mehr als nur der Stamm der Splitterspeere. Wenn Ihr seine Leiche noch nicht nach Informationen durchsucht habt, solltet Ihr dies tun, bevor Ihr weiterzieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13518] = { id = 13518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Welle Überlebender", description = "Für Laird ist es zu spät, er hat es nicht mehr rechtzeitig geschafft.\n\nDie letzte Welle Nachtelfen aus Auberdine hat vor ein paar Stunden versucht zu entkommen. Sie sind in ihrem alten Zuhause geblieben und haben sich an die Hoffnung geklammert, dass es gerettet werden kann, aber offenbar mussten sie sich letzten Endes den Naturgewalten beugen. Ich befürchte, dass viele von ihnen es nicht schaffen werden, so wie Laird.\n\nEilt Euch. Geht zur Küste im Westen hinunter und macht so viele Überlebende ausfindig, wie Ihr könnt. Wir schicken Schildwachen und Hippogryphen, aber jeder Augenblick zählt - wir müssen wissen, wer überleben könnte.", sourceObjective = "Macht alle überlebenden Flüchtlinge von Auberdine ausfindig.", completion = "Ich danke Euch, {class}. Manche von ihnen hätten es ohne Eure Hilfe nicht geschafft.\n\nWir werden die Verwundeten ins Hauptgebäude bringen, sobald alle sicher in der Stadt angekommen sind. Vielleicht könnt Ihr uns später dort aufsuchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13519] = { id = 13519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schattenhammer", description = "Eine Gruppe von Schattenhammerkultisten hat südwestlich von hier Lager aufgeschlagen. Sie stellen eine Armee von Wasserelementaren zusammen, die gegen Lor'danel eingesetzt werden könnte.\n\nIhr Anführer, der Hochkultist Azerynn, hat einen Pakt mit den dunklen Göttern geschlossen, die seinem Kult Macht über die Elemente gewähren. Kümmert Euch darum, bevor es zu spät ist, {name}.\n\nDer Kataklysmus hat die Elemente verwirrt... es ist nur eine Frage der Zeit, bis sie genug Elementare haben, um unsere Verteidigung zu übermannen.", sourceObjective = "Tötet Hochkultist Azerynn und 10 Fanatiker des Schattenhammers im Lager des Schattenhammers.", completion = "Ihr habt gute Arbeit geleistet, {name}. Der Schattenhammer ist ein gefährlicher Kult. Die Gefahr, die sie darstellen, zu unterschätzen, wäre die Tat eines Narren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13520] = { id = 13520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Meere", description = "Gut, Euch zu sehen. Dank Euch sind unsere Verwandten sicher nach Hause gekommen und ich hege Hoffnung, dass Ihr uns auch weiterhin helfen könnt.\n\nIhre Wunden werden so schlimm sein wie die von Laird - jeder einzelne wurde an der Küste arg mitgenommen und von den Elementaren angegriffen. Ich tue, was ich kann, aber es scheint, als hätten die Elementare ein Gift, das die Wundheilung einschränkt. Ich hoffe eine Salbe herstellen zu können, aber dazu benötige ich Sekret von Muschelmuskeln, die an der Küste zu finden sind. Könnt Ihr mir helfen?", sourceObjective = "Sammelt 16 verkrustete Muschelmuskeln.", progress = "Habt Ihr die Muschelmuskeln? Ich fürchte, wir haben nicht mehr viel Zeit.", completion = "Die sind ideal. Ich danke Euch vielmals!\n\nIch gehe davon aus, dass sie Euch selbst danken wollen, falls sie wieder zu Kräften kommen. Vielleicht könnt Ihr ja später noch einmal hierherkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13521] = { id = 13521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 413", description = "Seid gegrüßt!\n\nIch helfe Tharnariun dabei, herauszufinden, was die Tiere in der Gegend verderbt. Ich habe ein Gerät aufgestellt, das Tierteile und mögliche Verderbniserreger analysieren kann. Wenn Ihr mir ein paar gute Proben besorgen könnt, so werden wir schnell herausfinden, was es mit der Verderbnis auf sich hat.\n\nDas erste Gerät ist die Dröhnkiste 413. Sie steht am Strand östlich der Stadt. Besorgt das Fleisch der verderbten Gezeitenkriecher in der Nähe und bringt es zur Dröhnkiste, damit wir es analysieren können.", sourceObjective = "Sammelt 4 Proben verderbtes Gezeitenkriecherfleisch und bringt es zur Analyse zur Dröhnkiste 413.", progress = "<Die Dröhnkiste 413 dröhnt Euch erwartungsvoll entgegen.>", completion = "<Das Gerät knattert vor sich hin und plötzlich ertönt Hexknalls statische Stimme.>\n\nWunderbar! Ich hoffe, Ihr habt nicht zu viele getötet. Wir wollen sie nicht dem Aussterben nahe bringen, sondern nur schnell herausfinden, wo die Verderbnis herkommt! Ich fahre jetzt mit der Analyse fort.", sourceObjectiveStatus = "unverified-source-field" }
quests[13522] = { id = 13522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahr aus dem Wasser", description = "Ein paar der Überlebenden des letzten Angriffs von Auberdine versuchen noch immer, an die Küste und in Sicherheit zu gelangen. Wir haben vor weniger als einer Stunde erst erfahren, dass sie kommen. Ich wünschte, wir hätten mehr Vorwarnzeit gehabt...\n\nAn der Küste westlich von hier wimmelt es von bösartigen kleinen Wasserelementaren. Wir müssen sie beseitigen, wenn die Überlebenden es bis nach Lor'danel schaffen sollen. Macht Euch sofort auf den Weg und tötet jeden Elementar, den Ihr finden könnt.", sourceObjective = "Tötet 8 widerwärtige Gischte.", completion = "Wir sind Euch für Eure Anstrengungen sehr dankbar. Seit dem Kataklysmus sind die Elementare außer Kontrolle. Wir hegen wenig Hoffnung, Auberdine zurückzuerobern, ohne vorher die Elementare auszulöschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13523] = { id = 13523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über die Gezeiten", description = "Sorgt Euch nicht um mich. Meine Wunden sind tief und bald wird mich der Tod ereilen.\n\nNun liegt alles in Euren Händen... Ihr müsst den Schattenhammer aufhalten.\n\nDie Alten Götter, die von ihnen verehrt werden, haben ihnen Macht über die ruhelosen Wassergeister gewährt... diese Macht ist heikel. Kanalisiert Elunes Präsenz durch diese Kugel, sobald die Elementare besiegt sind.\n\nVerwendet die Macht Elunes, um die Geister für immer zu verbannen.", sourceObjective = "Wendet die Kugel von Elune an den Überresten von 6 wütenden Gezeitengeistern an.", completion = "Ihr habt es geschafft... nicht alles war vergebens...\n\nMeine Zeit ist gekommen. Geht nun, {name}. Möge Elune Euch beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13524] = { id = 13524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Silberwasser", description = "Ihr... Ihr seid keiner von ihnen? Schnell! Lasst mich raus!\n\nWir müssen schleunigst zur Ammertannhütte! Wenn Leutnant Dumont erst einmal herausfindet, wer diese Leute wirklich sind, dann wird diese Stadt in Schutt und Asche gelegt werden!", sourceObjective = "Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13525] = { id = 13525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist mit den Furbolgs der Schwarzfelle los?", description = "Unsere Vorfahren lebten schon seit Generationen friedlich neben den Furbolgs der Schwarzfelle. In letzter Zeit aber ist der Kontakt zu den Siedlungen abgebrochen, die sich tiefer im Wald befinden. Eines ihrer größeren Dörfer, Schwarzfellfeste, befindet sich südlich von hier.\n\nReist dorthin und findet den Ältesten Brolg. Fragt ihn, warum sich sein Volk von uns zurückgezogen hat und bietet Eure Hilfe an, wenn es ihrer bedarf.", sourceObjective = "Sprecht mit dem Ältesten Brolg in der Schwarzfellfeste.", completion = "Was verschlägt Euch hier her, Außenseiter?\n\n<Ihr erzählt dem Ältesten, dass Foriel Rundblatt vom Hain der Uralten Euch geschickt hat. Der Älteste scheint sich ein wenig zu beruhigen.>\n\nDer Elf hat Recht. Die Streitmächte aus Teufelswald sind bis zur Dunkelküste vorgedrungen und haben mein Volk krank gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13526] = { id = 13526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bärenklau", description = "Die garstigen Satyrn aus Teufelswald haben begonnen, ihr Gift an die Dunkelküste zu bringen, in unser Land. Die Verderbnis zerstört das Land und verdreht dessen Bewohner – auch mein Volk.\n\nUnsere Magie alleine reicht nicht aus, um sie wieder gesunden zu lassen. Es gibt allerdings eine Pflanze namens Bärenklau, mit der wir Fieber senken und die Schwachen stärken. Mit der Hilfe dieser Pflanze könnte auch der Einfluss der Satyrn geheilt werden. Ihr findet die Pflanze in der Wildnis in der Nähe des Dorfes.", sourceObjective = "Bringt 8 Stängel Bärenklau zum Ältesten Brolg in der Schwarzfellfeste.", progress = "Habt Ihr den Bärenklau?", completion = "Die Stängel sind kümmerlich und schwach, aber mehr haben wir nicht. Die Verderbnis verbreitet sich schnell und selbst die Pflanzen bleiben nicht verschont.", sourceObjectiveStatus = "unverified-source-field" }
quests[13527] = { id = 13527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über Geschmack lässt sich nicht streiten", description = "<Das Gerät rauscht ein paar Augenblicke lang, bevor Hexknalls Stimme ertönt.>\n\nInteressant! Der Ursprung der Verderbnis kommt definitiv von einer externen Quelle - was mich weniger verwundert - aber es scheint, als wurde sie durch das Essen verderbter Nahrung übertragen, ein großes Säugetier wahrscheinlich, ich würde auf einen Bären tippen.\n\nSucht den Strand nach dem Kadaver des Bären ab. Östlich von hier würde es am meisten Sinn ergeben, an der Seite des Strandes, die zum Landesinneren zeigt. Bringt mir eine Probe von seinem Fleisch.", sourceObjective = "Erhaltet die Probe eines faulenden Bärenkadavers östlich der Dröhnkiste 413.", progress = "Willkommen zurück! Habt Ihr den Kadaver gefunden und ihm eine Probe entnehmen können?", completion = "Das sieht eindeutig nach dem Zeug aus, das sie gegessen haben. Lasst mich das genauer anschauen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13528] = { id = 13528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dröhnkiste 723", description = "Wir konnten noch an ein paar anderen wilden Tieren eine Infektion feststellen. Es sind sogar gute Neuigkeiten, dass die Kriecher sich an den Bären angesteckt haben – hoffentlich lassen sich alle Fälle auf diese eine Quelle zurückführen. Jetzt müssen wir unsere Aufmerksamkeit den Bären widmen.\n\nDie Dröhnkiste 723 ist in der Nähe der Wasserfälle östlich von hier. Es ist keine schöne Arbeit, aber sie ist nötig: Ich brauche für die Analyse frische Bäreneingeweide für die Dröhnkiste. Mit weiteren Informationen können die nächsten Schritte leichter bestimmt werden.", sourceObjective = "Sammelt 6 Proben verderbte Eingeweide eines Distelbären und bringt sie für eine Analyse zur Dröhnkiste 723.", progress = "<Die Dröhnkiste 723 dröhnt Euch erwartungsvoll entgegen.>", completion = "<Es rauscht statisch, bevor Hexknalls verzerrte Stimme ertönt.>\n\nWir bekommen gerade die Ergebnisse. Wir sollten jeden Augenblick mehr Informationen darüber erhalten, wie die Bären sich die Verderbnis eingefangen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13529] = { id = 13529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ursprung der Verderbnis", description = "Ich habe mich auf den Weg gemacht, als ich die Neuigkeiten von Hexknall gehört habe. Ich weiß jetzt, wer hinter allem steckt: Zenn Faulhuf.\n\nEr kam von Teldrassil hierher, nachdem er von dort für das Wirken pervertierter Magie verjagt worden war. Die Art von Verderbnis, die er anwendet, ist in meinen Reihen nicht willkommen und es scheint als sei er dieses Mal einen Schritt zu weit gegangen. Vielleicht hat er es aus Rache getan.\n\nZenn wurde zu lange akzeptiert und es ist an der Zeit, dass wir diese Bedrohung all dessen, was natürlich ist, beseitigen. Tötet Zenn und seine Diener. Sucht mich dann in Lor'danel auf.", sourceObjective = "Tötet Zenn Faulhuf und 8 üble Grells in der Klippenquellgrotte.", completion = "Es ist vollbracht. Ich danke Euch. Ich hoffe nur, dass die Wildtiere nach seinem Tod etwas mehr Frieden finden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13537] = { id = 13537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lust auf Barsch", description = "Nach all dem Bootfahren und Bauen bin ich erschöpft... und hungrig. Wisst Ihr, worauf ich Lust habe? Fisch. Fisch klingt für mich jetzt unfassbar gut.\n\nDunkelküste ist für Barsch bekannt. Wenn Ihr mir welchen fischt, werde ich dafür sorgen, dass es sich für Euch lohnt.", sourceObjective = "Benutzt Eure Angelfertigkeit, um 4 Dunkelküstenbarsche zu erhalten.", progress = "<Ihr hört Johnathans Bauch knurren, als Ihr Euch nähert.>\n\nBesser hätten Worte es nicht ausdrücken können.", completion = "Es scheint, als sei Angeln etwas, das Euch liegt. Mein Bauch ist für dieses Geschenk sehr dankbar.\n\nIch glaube, Ihr könnt mit dieser Angelrute mehr anfangen als ich. Nehmt sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[13538] = { id = 13538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage aus dem Süden", description = "Die drei Türme südlich des Tausendwinterflusses entziehen der Festung Energie!\n\nMacht den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm dem Erdboden gleich und erstattet mir dann Bericht. Denkt dran, nur Belagerungsmaschinen können einen Turm beschädigen, deshalb müsst Ihr sie gut vor der Horde beschützen!", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Ahbramis in Tausendwinter zurück.", completion = "Ich habe die Explosion bis hier gehört! Gute Arbeit - wir haben schon damit begonnen, die Energie in das Relikt der Titanen umzuleiten, um eine Superaufladung für unsere eigenen Truppen zu ermöglichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13539] = { id = 13539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einstürzende Turmbauten", description = "Während die Allianz gegen unsere Türen hämmert, schaut ein wahrer Taktiker über das Offensichtliche hinaus.\n\n\"Greif ihn an, wo er unvorbereitet ist, erscheine, wo du nicht erwartest wirst.\"\n\n{name}, überquert den Tausendwinterfluss und macht einen der drei Türme im Süden dem Erdboden gleich. Unsere Hexenmeister berichten, dass die Türme Energie abziehen, die wir benutzen könnten, um unsere eigenen Truppen zu stärken.\n\nKehrt zu mir zurück, sobald Ihr einen Turm zerstört habt.", sourceObjective = "Zerstört den Schattenblickturm, den Flammenaugenturm oder den Wintersturzturm und kehrt zu Taktikoffizier Kilrath in Tausendwinter zurück.", completion = "Und nun, um den Feind zu vernichten, muss der Zorn unserer Truppen geweckt werden. Um den Vorteil darin zu sehen, den Feind zu besiegen, müssen sie ihre Belohnungen erhalten. Ich hoffe, dass dies hier Euren Dienst an der Horde ausreichend entlohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13542] = { id = 13542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen den Wind", description = "Wenn wir die Ruinen von Auberdine aus den Händen des Schattenhammers zurückerlangen möchten, so müssen wir uns dauerhaft um die Elementare kümmern, die sie beschworen haben.\n\nHier kommt Ihr ins Spiel.\n\nIch erwarte nicht, dass Ihr die Stadt alleine einnehmt, aber während wir hier oben heilen, könnt Ihr sie für uns schonmal weichklopfen.\n\nUm mit den rasenden Zyklonen auf lange Sicht fertigzuwerden, müsst Ihr Euch nach Westen begeben, sie töten, ihre Armschienen an Euch nehmen und sie in den Mondbrunnen werfen. Das wird die Armschienen zerstören und verhindern, dass die Elementare wieder beschworen werden können.", sourceObjective = "Benutzt den Mondbrunnen in den Ruinen von Auberdine, um 8 Armschienen des rasenden Zyklons zu zerstören.", completion = "Ich kann Euch gar nicht genug danken, {name}. Nun haben wir eine realistische Chance, die Ruinen zurückzuerobern, sobald wir uns erholt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13543] = { id = 13543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Hammer zu Brechen...", description = "Ich bin über die Ruinen von Auberdine geflogen, um das Gebiet auszukundschaften. Drei Schattenhammerkultisten dort sind für die Elementare verantwortlich, die die zerstörte Stadt eingenommen haben.\n\nBegebt Euch zu den Ruinen westlich von hier. Sucht und besiegt Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und den Himmelsfürst Braax.\n\nWenn sie aus dem Weg geschafft sind, werden Schildwache Selarin und ihre Truppen eine Chance haben, ihre Heimat zurückzuerobern.", sourceObjective = "Tötet Wolkenzähmerin Wildmähne, Windmeister Tzu-Tzu und Himmelsfürst Braax.", completion = "Ohne dass die Drei hier weiter Elementare anlocken, wird es in den Ruinen von Auberdine weitaus weniger von ihnen geben.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13544] = { id = 13544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bärensegen", description = "Bevor der Bärenklau verwendet werden kann, um die Betroffenen zu reinigen, müssen wir ihn dafür vorbereiten und segnen. Nördlich von unserem Dorf ist ein Weitschreiter namens Flinkfuß zu finden. Um das Bündel zu vervollständigen, brauchen wir seine Schwanzfedern.\n\nBringt die Schwanzfedern und das Bärenklaubündel zur uralten Bärenstatue in den Ruinen beim Hain der Uralten, noch weiter nördlich als Flinkfuß.\n\nFügt am Schrein die Schwanzfedern dem Bärenklau hinzu und erhaltet den Segen des Bärengeists.", sourceObjective = "Bringt das gesegnete Kräuterbündel zum Ältesten Brolg in Schwarzfellfeste.", progress = "Wart Ihr bei der uralten Bärenstatue?", completion = "<Der Älteste Brolg nimmt das gesegnete Bündel entgegen und betrachtet es.>\n\nDas ist genau das, was ich brauche. Der Bärengeist ist uns wohlgesinnt und es gibt doch noch Hoffnung für meine Brüder.", sourceObjectiveStatus = "unverified-source-field" }
quests[13545] = { id = 13545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befallenen reinigen", description = "Mit den vom Bärengeist gesegneten Pflanzen im Kräuterbündel können meine Brüder nun gereinigt werden. Die Verderbnis aus Teufelswald hat sie in den Wahnsinn getrieben und sie greifen jeden an, der ihnen zu nahe kommt. Ihr müsst damit rechnen, dass die Befallenen feindlich auf Euch reagieren werden, bis Ihr die Geister der Verderbnis getötet habt, die sie verfolgen.\n\nKehrt zu mir zurück, wenn Ihr meine Brüder von der Verderbnis befreit habt.", sourceObjective = "Der Älteste Brolg möchte, dass Ihr das gesegnete Kräuterbündel benutzt, um 7 Furbolgs der Schwarzfellfeste zu läutern und die Geister der Verderbnis, die sie in den Wahnsinn treiben, tötet.", completion = "Ihr habt gute Taten vollbracht. Mein Volk beginnt, sich von dem Wahnsinn zu lösen. Wenn der Ursprung der Verderbnis jedoch weiterhin hier ist, so werden sie bald wieder verderbt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13546] = { id = 13546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schänder", description = "Die Jadefeuersatyrn von Teufelswald haben sich ihren Weg zur Dunkelküste gebahnt und jedem Land, jedem Wasser und jeder Kreatur unterwegs die Verderbnis auferlegt. Ihr habt gesehen, was die Verderbnis mit meinem Volk und unserer Heimat angestellt hat. Wenn wir die Satyrn nicht bekämpfen, so wird unser Schicksal das Gleiche sein.\n\nIn der Höhle östlich von hier ist Sharax der Schänder zu finden, der Satyr, der für das Leiden der Schwarzfelle verantwortlich ist. Tötet ihn, {name}, und befreit uns von seinem Einfluss. Zeigt den Satyrn, dass die Schwarzfelle nicht so leicht unterzukriegen und zu verderben sind.", sourceObjective = "Der Älteste Brolg in der Schwarzfellfeste möchte, dass Ihr Sharax den Schänder tötet.", completion = "Vielen Dank, {name}. Ihr werdet von meinem Volk als Held gefeiert. Ohne Euch wären wir dem Wahnsinn und dem Tod ausgesetzt gewesen. Möge der große Bärengeist immer über Euch wachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13547] = { id = 13547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister locken", description = "Eure Freunde im Flüchtlingslager sind sich der tatsächlichen Gefahr nicht bewusst, welche die Schattenhammerkultisten bereits über die Welt gebracht haben.\n\nDamit Ihr Euch der Sache annehmen könnt, müsst Ihr zuerst Hilfe von den Toten aus Auberdine bekommen.\n\nSucht in den Ruinen der Stadt nach den Leichen von Thundris Windwirker, Elissa Sternenhauch, Taldan, und Caylais Mondfeder. Lockt die Geister aus ihren Körpern heraus und bringt sie zu mir.", sourceObjective = "Lockt die Geister von Thundris Windwirker, Elissa Sternenhauch, Taldan und Caylais Mondfeder.", completion = "So viel Tod und Schmerz. Und zweifellos wird es noch mehr davon geben.\n\nAlles, was ich will, ist doch nur die Umarmung der Göttin spüren, so wie die anderen.\n\nZuerst müssen wir aber versuchen, mehr Leid und Zerstörung zu verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13548] = { id = 13548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[13549] = { id = 13549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Männchen oder Weibchen?", description = "Ich bin daran interessiert, neben den Artefakten der Drakkari auch ein paar Tiere von Zul'Drak mit mir zurück nach Zandalar zu bringen. Männchen der Frostleoparden und Eispfotenbären habe ich schon – ich brauche aber Weibchen!\n\nZu dumm, dass mein Fallensteller in einem überaus unglücklichen Unfall ums Leben kam. Wäret Ihr vielleicht dazu bereit, für ihn einzuspringen?\n\nSchläfert die Leoparden und Bären mit diesem Blasrohr ein und vergewissert Euch, dass es auch Weibchen sein werden, die Ihr dann zu mir zurückbringt, wenn Ihr so nett wärt. Finden könnt Ihr sie an den Altären von Rhunok, Quetz'lun und Har'koa.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr mit To'kinis Blasrohr Frostleoparden und Eispfotenbären einschläfert. Kehrt mit jeweils 3 Weibchen zu ihm zurück.", completion = "Wirklich sehr ausgezeichnete Exemplare, {name}! Sie werden mit Sicherheit für Neugierde und stundenlange Spekulationen unter meinen Kollegen zuhause sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13554] = { id = 13554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung im Dunkeln", description = "<Das Gerät spuckt ein paar zusammenhangslose Wortfetzen aus, bevor Hexknalls Stimme wiederzuerkennen ist.>\n\nNachtratten! Sie haben Nachtratten gefressen! Diese kleinen Nervensägen kommen nur von einem Ort, einer Höhle an den Klippen östlich von hier. Ihr müsst nach Nordosten gehen, um zu dem Pfad zu gelangen, der zu den Höhlen führt - sucht nach einer Öffnung unter dem Wasserfall.\n\nDie Nachtratten dort brüten entweder etwas Übles aus, oder jemand hat ihnen einen Verderbniserreger absichtlich zukommen lassen. In jedem Fall brauche ich Proben von dem Zeug!", sourceObjective = "Erhaltet 6 Proben widerlicher Schleim von den Kreaturen in der Klippenquellgrotte.", progress = "Habt Ihr das Zeug bekommen? Je früher ich an einem Heilmittel arbeiten kann, umso schneller können wir die Tiere retten!", completion = "Das sollte mehr als genug sein! Vielen Dank! Ich fange sofort an, an dem Heilmittel für dieses Übel zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13556] = { id = 13556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eier für Dubra'Jin", description = "Wie geht's, Mann? Was meinst du, kannst du mir helfen? Bah'Kini braucht 'ne Menge Raptoreier, um sie Dubra'Jin zu opfern.\n\nWas denkst du denn, wieso uns die Drakkari noch nicht überrannt haben?! Ja weil Dubra'Jin uns hilft!\n\nDu musst für uns die Raptoreier sammeln - die sind hier in Gundrak bei den Bäumen. Manchmal tragen die Raptoren sie auch rum, damit sie warm bleiben.", sourceObjective = "Ha'wana in Dubra'Jin möchte, dass Ihr 12 Raptoreier von Gundrak sammelt.", progress = "Wer hätt gedacht, dass der große Dubra'Jin so viele Eier haben will? Was will der eigentlich mit denen?", completion = "Eins, zwei, drei... hehe, das wird reichen, Mann! Jetzt werden wir für 'ne ganze Weile sicher sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13557] = { id = 13557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Glücks", description = "Dieser Schlüssel scheint für die Käfige zu sein, die überall in der Klippenquellgrotte verstreut sind. Tharnariun würde sich sicher freuen, wenn Ihr die Situation nutzt, um die Nachtratten und Distelbären zu befreien, die nicht verderbt wurden und gefangen gehalten werden.", sourceObjective = "Befreit 8 unverderbte Distelbären oder unverderbte Nachtratten aus den Käfigen in der Klippenquellgrotte.", progress = "Ja, {race}?", completion = "Gut zu hören, dass Ihr ein paar der Wildtiere befreien konntet. Mit ein wenig Glück werden wir ein Heilmittel finden, bevor die Verderbnis die anderen Tiere umbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13558] = { id = 13558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner herbeirufen", description = "Aetherion ist zwar schon fast in unserer Welt, aber trotzdem können wir ihn noch ausschalten!\n\nAm Ende des Docks schwebt eine Ritualkugel. Ich möchte, dass Ihr mit ihr das Ritual vollendet und den Elementarlord aus seinem Vortex holt.\n\nVertraut mir, {name}, ich und die anderen von Euch befreiten Geister werden Aetherion extrem schwächen. Allerdings müsst Ihr ihm den letzten Stoß versetzen, um das Volk der Kaldorei aus Dunkelküste vor der Zerstörung zu retten.\n\nBringt die Essenz Aetherions zu Corvine Mondaufgang im Flüchtlingslager, damit er Bescheid weiß.", sourceObjective = "Benutzt Aetherions Ritualkugel und erhaltet Aetherions Essenz.", progress = "Ihr seid zurückgekehrt. Welche Neuigkeiten bringt Ihr mir?", completion = "Yalda? Die Geister der anderen aus den Ruinen von Auberdine?\n\n<Der Druide denkt über Eure Erlebnisse in den Ruinen nach.>\n\nIch kann mich an alle erinnern. Wir werden sie sehr vermissen, aber sie haben nun zum Wohle aller die Umarmung der Göttin gefunden.\n\nAnde'thoras-ethil, mögen Eure Schwierigkeiten geringer werden, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13559] = { id = 13559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Tribut", progress = "Gewöhnlicher Tribut war nicht gut genug für den großen Hodir, als er unter den Frostriesen wandelte.\n\nEr mag zwar nicht mehr bei uns sein, doch wir haben die Tradition beibehalten, seiner Stärke und Weisheit Tribut zu zollen. Es täte Eurem Ruf sehr gut, wenn Ihr Euch an dieser Tradition beteiligen würdet, kleiner {class}.", completion = "Die Söhne Hodirs nehmen Euren Tribut an, kleines Wesen. Ihr schreitet voran auf Eurem Weg, Euren Wert als Verbündeter zu beweisen - auf mehr als eine Art." }
quests[13560] = { id = 13560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nicht so tiefe Ozean", description = "Ihr seht sehr fähig aus!\n\nAn der Küste hier sind viele Wracks - viele alte und ein paar neue. Ich versuche schon seit einiger Zeit, mich darum zu kümmern und die wertvollen Reste besser zu nutzen, aber die Murlocs, die sich dort breitgemacht haben, haben andere Vorstellungen. Ich habe viele Abenteurer losgeschickt und keiner kam zurück.\n\nSorgt Euch nicht, ich habe meine Lektion gelernt und Euer Schicksal wird ein anderes sein. Schwimmt in Richtung Norden und sucht Gary - er wird Euch den neuen Plan erklären. Es ist ganz einfach.", sourceObjective = "Gorbold Stahlhand möchte, dass Ihr Gary aufsucht, um weitere Anweisungen zu erhalten.", completion = "Die Ablenkung hat also funktioniert? Gut! Macht Euch wegen der Schätze keine Sorgen. Ich und Gary werden uns darum kümmern, diesmal.\n\nUm ehrlich zu sein glaube ich, dass sie mich aus der Stadt verjagen würden, wenn noch mehr schief läuft und noch ein weiterer Abenteurer verloren geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13561] = { id = 13561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trost für die Hochgeborenen", description = "Ich bin nach Bashal'Aran gekommen, um den besorgten Geistern der Hochgeborenen Frieden zu gewähren, aber mit jedem Hieb scheint meine Hand sich mehr zu wehren. Wenn Ihr mir helfen wollt, so könnt Ihr Euch meiner Dankbarkeit sicher sein.", sourceObjective = "Tötet 6 verfluchte Hochgeborene und 6 zuckende Hochgeborene.", completion = "Ihr habt meinen Dank. Und auch wenn man es ihnen nicht anmerkt, den Dank der Geister der Hochgeborenen habt Ihr auch.\n\nEine sichere Reise wünsche ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13562] = { id = 13562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Flamme von Bashal'Aran", description = "In Zeiten wie diesen müssen wir innehalten und unsere Lebensweise überdenken. Wir sind nun sterblich und egal, wie sehr wir auch etwas anderes bevorzugen würden, wir verdienen den Platz, den wir nun in dieser Welt einnehmen.\n\nBashal'Aran, einst die Stadt unserer Vorfahren, ist nun die Heimat ihrer verfluchten Geister. Ihr findet Bashal'Aran, wenn Ihr der Straße in Richtung Süden folgt. Wir hatten Hoffnung gehegt, Rettung zu finden, aber wir haben sie zu lange leiden lassen. Es ist an der Zeit, die letzte Flamme von Bashal'Aran auszulöschen.", sourceObjective = "Löscht die letzte Flamme von Bashal'Aran aus.", completion = "Ihr habt unseren Dank. Es ist an der Zeit, die Vergangenheit hinter uns zu lassen und uns der Zukunft zu widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13563] = { id = 13563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewige Liebe", description = "Ich möchte Euch meinen Dank für unsere Rettung aussprechen. Man könnte behaupten, ich hätte Glück gehabt, doch meine geliebte Anaya ist schon lange tot. Ich bin einsam und in Schwierigkeiten und leider benötige ich schon wieder Eure Hilfe.\n\nNach meiner Rettung bin ich in den Wäldern von Dunkelküste umhergewandert und habe die Ruinen von Bashal'Aran entdeckt... und sah den Geist meiner geliebten Anaya.\n\nSie muss befreit werden, doch ich selbst bekomme es nicht übers Herz. Ihr Geist muss zerstört werden.", sourceObjective = "Befreit den Geist von Anaya Dämmerflucht und erhaltet ihren Anhänger.", progress = "Es ist mir irgendwie gelungen, nicht mit dem gleichen Gift in Berührung zu kommen wie all die anderen. Doch in gewissem Sinne beneide ich sie sogar... eine Ewigkeit in Einsamkeit zu verbringen erscheint kaum lebenswert.\n\nIch vermisse dich so sehr, Anaya.", completion = "Ich danke Euch, {name}. Vielleicht wäre es besser gewesen... wenn ich es selbst getan hätte. Doch selbst nach Tausenden von Jahren konnte ich die Hand nicht gegen sie erheben.\n\nIch bitte Euch, lasst mich nun allein in meiner Trauer...", sourceObjectiveStatus = "unverified-source-field" }
quests[13564] = { id = 13564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlorener Freund", description = "Bitte helft mir... Ich kann mich kaum aufsetzen.\n\nMein Freund, ein Bär namens Grimmklaue, ist nicht hier. Ich habe ihn vorausgeschickt, um den Schildwachen unsere Ankunft anzukündigen, bevor wir Auberdine verließen, doch er kam nie an. Ich spürte bereits, dass etwas nicht in Ordnung war, als wir uns auf den Weg machten, aber durch die Evakuierung konnte ich der Angelegenheit nicht nachgehen.\n\nSollte er sich verletzt haben, so gibt es nur einen Ort, den er aufsuchen würde: das Welkende Dickicht nördlich von Auberdine, an der Straße südlich von hier. Bringt ihn sicher zu mir zurück... ich habe niemanden außer ihm.", sourceObjective = "Findet Grimmklaue.", completion = "Seid gegrüßt. Ihr scheint Interesse an meinem Freund zu haben. Ich nehme an, sein Freund Volcor hat Euch geschickt? Wenn er nicht selbst gekommen ist, so muss auch er verwundet sein. Ich hoffe, er wird bald gesunden.\n\nGrimmklaue ist zu schwer verletzt, um weit transportiert werden zu können, und er muss dringend behandelt werden. Ich fürchte, ich kann nicht zulassen, dass Ihr ihn mitnehmt, aber vielleicht könnt Ihr mir dabei helfen, mich um ihn zu kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13565] = { id = 13565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweiten Grades", description = "Unbesonnene Gewalt können wir nicht gutheißen - das liegt nicht in unserer Natur. Doch mitunter bringt die Vermeidung von Kämpfen unübersehbare Folgen mit sich, wie in unserem Fall mit den Naga.\n\nAls die Erde in dieser Gegend brach, erschienen östlich von hier kleine Ruinen. Diese Ruinen waren einst die Heimat der Untertanen Königin Azsharas. Nun scheint es, als sei dieses Volk auf der Suche nach etwas zurückgekehrt.\n\nNehmt diese versteinerte Wurzel. Ihr könnt sie auf ihre Gefallenen anwenden und Ents zu Hilfe rufen. Kümmert Euch schleunig um sie und ihre Anführerin.", sourceObjective = "Benutzt die versteinerte Wurzel, ruft 6 siechende Ents und entledigt Euch Lady Janiras, der Anführerin der Naga.", completion = "Ich danke Euch, Verbündeter. Wir werden wachsamer sein, sollten sie wiederkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13566] = { id = 13566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materialien für das Ritual", description = "Während wir uns um Grimmklaue kümmern, möchte ich Euch bitten, kampflos von den Wildtieren ein paar Materialien für das Ritual zu sammeln.\n\nIch benötige Schnurrhaare eines Mondpirschers westlich von hier - geht zu den schlafenden Mondpirschern und versucht, ihnen die Haare auszureißen, und entfernt Euch, bevor sie aufwachen.\n\nIch brauche auch Haare der Rehe östlich von hier, aber meidet die Hirsche.\n\nUnd zu guter Letzt brauche ich das Fell der Bären beim Wasser nordöstlich von hier. Wartet, bis sie einen Fisch gefangen haben, besorgt die Fellprobe, und entfernt Euch von den Bären, bevor sie aufgegessen haben.\n\nBitte, fügt ihnen keine Schmerzen zu.", sourceObjective = "Besorgt 3 Schnurrhaare eines Mondpirschers, 3 Büschel gefleckter Rehhaare und 3 Proben Distelbärenfell.", progress = "Habt Ihr die Materialien, um die ich Euch gebeten habe? Und bitte sagt mir, dass Ihr den Tieren keine Schmerzen zugefügt habt, um sie zu erhalten.", completion = "Diese Materialien sind perfekt. Sie sind die letzten Zutaten für einen speziellen Weihrauch, an dem ich arbeite. Ich werde es Euch gleich erklären - lasst mich die Zutaten nur schnell vermischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13567] = { id = 13567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Hirsches", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.\n\nWenn Ihr Euch mit dem großen Hirschgeist verbünden wollt, so bringt diesen Weihrauch zu den Wäldern nördlich von Bashal'Aran. Meditiert vor dem großen Geist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Hirschgeists einzuholen.", completion = "Ich sorge für mein Volk. Ich führe es nicht mit Gewalt, sondern mit Weisheit und Schnelligkeit. Weisheit leitet uns tiefer in die Wälder, wenn Gefahr droht, und Schnelligkeit sorgt dafür, dass unsere Feinde nur noch unsere Abwesenheit feststellen können.\n\nDank meiner Weisheit kann ich Eure wahren Absichten hinter der Bitte nach meinem Segen sehen und weiß, dass Ihr den Segen meiner Schnelligkeit verdient. Ihr werdet ihn erhalten, doch Ihr müsst Euch darüber im Klaren sein, dass die anderen Geister Euch nicht mehr willkommen heißen werden, sobald Ihr ihn habt. Überlegt Euch gut, ob dies Euren Wünschen entspricht, bevor ich Euch meinen Segen erteile.", sourceObjectiveStatus = "unverified-source-field" }
quests[13568] = { id = 13568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Mondpirschers", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister zuschreiben.\n\nWenn Ihr Euch mit dem großen Mondpirschergeist verbünden wollt, so bringt diesen Weihrauch in die Länder südlich der Ruinen von Lornesta. Meditiert vor dem großen Mondpirschergeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Mondpirschergeists einzuholen.", completion = "Ich teile diese Wälder gerne und akzeptiere Nachtelfen in meiner Heimat - manchmal bezeichne ich sie sogar als Freunde. Auch wenn sie in letzter Zeit viel unter der Verderbnis gelitten haben, so kann ich doch in Euch die gleiche Stärke, Ehre und auch das Temperament sehen, das ich an ihnen schätze.\n\nWenn Ihr den Wert der Wildheit erkennt, die zur Bezwingung mancher Probleme wichtig ist, so bin ich bereit, Euch meinen Champion zu nennen. Ihr müsst jedoch wissen, dass Euch die anderen Geister nicht akzeptieren werden, wenn Ihr Euch mir verschreibt. Überlegt Euch diese Entscheidung gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[13569] = { id = 13569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bund des Rituales", description = "Ich werde mich um Grimmklaue kümmern, bis er sich vollständig erholt hat. Bald wird er bereit sein, in seine Heimat zurückzukehren. Ich habe eine weitere Aufgabe für Euch, während wir warten...vielmehr möchte ich Euch einen Gefallen tun, wenn Ihr dies wünscht.\n\nDie großen Geister der Wildtiere sind unter uns und warten auf Hilfe, um die Zerstörung aufzuhalten. Sie sind immer bei uns, auch jetzt, und mit den Materialien, die Ihr mir gebracht habt, kann ich Euch ermöglichen, sie zu sehen. Sprecht mit den Geistern, wählt einen von ihnen und kehrt mit dem Segen dieses Geistes zu mir zurück.", sourceObjective = "Atmet den Weihrauch vor Bewahrer Karithus ein und trefft eine Entscheidung zwischen dem Segen des großen Hirschgeistes, des großen Distelbärgeistes und des großen Mondpirschergeistes.\n\nNur einer der Geister kann Euch seinen Segen erteilen, also wählt weise.", completion = "Es ist vollbracht. Ihr habt den Segen eines der großen Geister erhalten und nun kann ich das Ritual mit Euch abschließen. Bitte haltet still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13570] = { id = 13570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Andenken an Auberdine", sourceObjective = "Ich möchte Euch meinen tiefsten Dank für Eure Hilfe aussprechen. In meiner Trauer habe ich Euch zuvor nicht die Dankbarkeit entgegengebracht, die Ihr verdient hättet. Ohne Euch wären wir jetzt wohl nicht hier.\n\nSeid Euch gewiss, dass Ihr hier immer Freunde haben werdet.\n\nUnd sorgt Euch nicht um meine Einsamkeit. Grimmklaue ist gute Gesellschaft und er bietet mir mehr Trost, als ich erwartet hätte.\n\nNehmt dies und unseren Segen, bis wir einander wiedersehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13571] = { id = 13571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fletchers Fundbüro", sourceObjective = "Durch den Gestank nach etwas Abgestandenem und Ungewaschenem hindurch dringt Euch bekannter Geruch in die Nase! Es scheint, als wäre dieser einst so mächtige Abenteurer ganz verrückt nach Kungaloosh.\n\nAls Ihr durch die Gitterstäbe schaut, könnt Ihr gerade so eben das Rezept erkennen, das auf seinem Arm steht...", sourceObjectiveStatus = "unverified-source-field" }
quests[13572] = { id = 13572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jadefeuerkohlenpfannen", description = "Die Satyrn aus Teufelswald haben angefangen, Hass und Verderbnis in unsere Länder zu bringen. Sie haben Sharax den Schänder geschickt, um Teile des Waldes zu unterwerfen, den wir Schwarzfelle unsere Heimat nennen.\n\nEr vergiftet nicht nur das Land, die Tiere und die Pflanzen, sondern hat auch überall im Dorf Jadefeuerkohlenpfannen aufgestellt, die ihm dabei helfen, Kontrolle über mein Volk zu erlangen. Die Kohlenpfannen zu zerstören, wird ihn allein nicht aufhalten können, aber es wird seinen Einfluss mindern, während wir mit dem Ältesten Brolg zusammen unsere Brüder befreien können.", sourceObjective = "Gren Fetzfell in der Schwarzfellfeste möchte, dass Ihr 8 Jadefeuerkohlenpfannen zerstört.", completion = "Ich danke Euch, {name}. Dank Euren Anstrengungen können wir vielleicht die übrigen Schwarzfelle retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13573] = { id = 13573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malfurions Rückkehr", description = "Wir haben erst vor kurzem die Neuigkeiten von Malfurions Erwachen gehört, nur Augenblicke, bevor der Kataklysmus über uns hereinbrach.\n\nKaum, dass er zu sich gekommen war, stieß er eine mysteriöse Warnung aus: das Land würde sich spalten, wenn nichts unternommen würde, und die Schockwellen würden über Dunkelküste zusammenlaufen.\n\nDann machte er sich - Berichten zufolge - in diese Richtung auf. Ich wurde hierher geschickt, um nach ihm zu suchen, habe aber nun alle Hände damit zu tun, den Flüchtlingen zu helfen.\n\nVielleicht könnt Ihr für uns südöstlich von hier nach ihm suchen.", sourceObjective = "Sucht nach Malfurion Sturmgrimm beim Auge des Vortex südöstlich des Flüchtlingslagers in Dunkelküste.", completion = "Es gilt, keine Zeit zu verschwenden, {class}. Es nimmt jedes bisschen meiner Energie in Anspruch, die Landmasse Dunkelküstes zusammenzuhalten und zu verhindern, dass sie einfach in den Ozean gerissen wird... Ihr müsst mir gut zuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13575] = { id = 13575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Land im Blut", description = "Wenn wir die Naturgewalten stabilisieren möchten, so können wir jedes bisschen Hilfe gebrauchen. Die Furbolgs des Schwarzfellstammes haben diese Gegend schon lange zu ihrer Heimat erklärt und sind mit dem Land eng verbunden.\n\nIhr Schamane und Ältester Braunpfote hat große Macht über die Elemente. Seine Hilfe wäre von unschätzbarem Wert. Versucht, ihre Unterstützung zu erhalten.", sourceObjective = "Sprecht mit dem Ältesten Braunpfote im Lager der Schwarzfelle südwestlich des Auges des Vortex.", completion = "Dem großen Malfurion Sturmgrimm zolle ich viel Respekt. Ich kann mein Volk in diesen schlimmen Zeiten jedoch nicht alleine lassen. Vielleicht gibt es eine Möglichkeit, wie wir einander helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13576] = { id = 13576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenseitige Hilfe", description = "Da viele meiner Brüder vom Wahnsinn oder von der Verderbnis eingenommen worden sind, habe ich kaum eine Wahl, als mich mit Euch zu verbünden. {race}, Ihr könnt auf unsere Hilfe zählen... sobald ich weiß, dass ich auf Eure zählen kann.\n\nWie Ihr sehen könnt, haben wir hier ein paar Probleme mit den Feuerelementaren. Helft uns, sie zu bekämpfen, und wendet dieses Totem auf ihre feurigen Überreste an.\n\nWir werden dafür sorgen, dass sie dahin zurückgehen, wo sie herkamen - ob es ihnen gefällt oder nicht.", sourceObjective = "Benutzt das besänftigende Totem, um die Überreste von 8 unbändigen Feuerelementaren zu absorbieren.", completion = "Das Element Feuer ist einzigartig in seiner Eigenschaft, sich oft weiter auszubreiten, wenn man es willkürlich angreift... und so den Flammen noch mehr Angriffslust verleiht.\n\nWir werden jedoch besonnen vorgehen, {name}. Wir werden es endgültig bekämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13577] = { id = 13577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Wildekin", description = "Es gab einst viele Wildekin in Dunkelküste. Sie waren so eng mit dem Land verbunden, das vom Kataklysmus zerstört wurde, dass ihre Zahlen stark zurückgingen.\n\nAroom ist der letzte Wildekin seines Stammes; er ist ein mächtiger Ältester mit einer starken Verbindung zu Elune. Seine Hilfe wird zur Heilung des Landes unumgänglich sein. Ihr könnt ihn nördlich von hier beim Mondbestrahlten Bau finden.", sourceObjective = "Sprecht mit Aroom beim Mondbestrahlten Bau nördlich vom Auge des Vortex.", completion = "Die Kreatur scheint versunken in tiefe Trauer. Ihre Augen starren durch Euch hindurch, als Ihr Euch nähert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13578] = { id = 13578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arooms Abschied", description = "<Die Kreatur ruft traurig, und wendet sich Euch zu.>\n\nAroom ist Letzter von Stamm...\n\nAndere nicht ruhen... brauchen Scheiterhaufen. Bringt Aroom Federn der anderen... sie müssen ruhen.\n\nAroom hilft Euch dann.", sourceObjective = "Erhaltet 8 Federn von getöteten Wildekin.", progress = "Ihr bringt Federn?", completion = "Ich danke Euch. {race}, bald kann mein Stamm ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13579] = { id = 13579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beschützer von Ameth'Aran", description = "Nichts heilt das Land schneller als die Stärke seiner Bewohner. Wir Nachtelfen haben das Glück, dass ein paar unserer besten Verbündeten sowohl das Land als auch dessen Bewohner zugleich sind. \n\nSelenn, ein Urtum des Krieges, wurde mit der Bewachung der Ruinen von Ameth'Aran südlich von hier beauftragt. Geht dorthin und ersucht seine Hilfe.", sourceObjective = "Sprecht mit Selenn in den Ruinen von Ameth'Aran.", completion = "Wenn der große Malfurion meine Anwesenheit verlangt, so ist es meine Pflicht, dieser Aufforderung Folge zu leisten. Es ist aber auch meine Pflicht, diese Ruinen zu beschützen.\n\nVielleicht könnt Ihr mir helfen, beiden Aufgaben nachzukommen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13580] = { id = 13580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elemente beruhigen", description = "Die Geister der Feuerelemente sind nun in dem Totem aufbewahrt. Bringt es zur Spitze des Gezackten Riffs am Lodernden Strand und platziert es dort.\n\nDie besänftigende Energie des Totems wird die Elementare langsam umspülen, bis ihre Wut abgeklungen ist.\n\nIhr müsst das Totem beschützen, denn Feuer reagiert auf das Ritual der Besänftigung alles andere als wohlgesinnt.", sourceObjective = "Platziert das aufgeladene Besänftigungstotem auf der Spitze des Gezackten Riffs am Lodernden Strand und beschützt es, bis das Ritual abgeschlossen ist.", completion = "Wir stehen in Eurer Schuld, {name}. Vielleicht können wir nun mit Malfurions Hilfe den Rest von Dunkelküste retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13581] = { id = 13581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Schwarzfelle", description = "Es wird zwar nicht unverzüglich geschehen, doch bald wird der Ärger der Elementare abklingen und mein Volk wird weiterleben.\n\nIch werde Euch und Malfurion helfen, soweit es in meiner Macht steht.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", completion = "Das sind gute Nachrichten, {name}. Die Furbolgs mögen auf den ersten Blick wie ein Volk der Wilden erscheinen, aber ihre Verbindungen zum Land sind uralt und ihre Schamanen sind ohnesgleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13582] = { id = 13582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Feuer Elunes", description = "Wir brauchen für Ritual besondere Flamme - Feuer Elunes.\n\nGeist Horoo ist östlich von hier. Horoo trägt Elunes Flamme. Bringt Flamme, um Geister zu Ruhe zu bringen.\n\nIhr habt Arooms Dank.", sourceObjective = "Erhaltet Elunes Fackel von Horoo dem Flammenbewahrer.", progress = "Ihr habt Fackel?", completion = "<Aroom heult in tiefen Tönen auf.>\n\nEndlich Brüder können ruhen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13583] = { id = 13583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Wildekin", description = "Wildekin bei Elune. Aroom in Eurer Schuld.\n\nAroom hilft Euch. Kehrt zu Malfurion zurück. Aroom kommt nach.", sourceObjective = "Kehrt zu Malfurion Sturmgrimm beim Auge des Vortex zurück.", completion = "Die Wildekin waren einst die Wächter des Landes. Es ist gut zu hören, dass Aroom dies nicht vergessen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13584] = { id = 13584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erde beruhigen", description = "Ich würde meine Verantwortung vernachlässigen, wenn ich meinen Posten verließe, gerade jetzt, wo so viele Elementare in den Ruinen außer Kontrolle herumtoben.\n\nLasst uns zuerst die Elementare beseitigen, bevor wir uns überlegen, wie wir Malfurion helfen können. Was meint Ihr, <kleiner/kleine:c> {class}?", sourceObjective = "Tötet 8 wütende Erdelementare.", completion = "Es ist offensichtlich, {name}. Die Elemente werden sich nicht beruhigen, bis Malfurion das Gleichgewicht wieder ins Land gebracht hat. Wenn ich ihm helfe, so gehe ich gewissermaßen auch meiner Arbeit nach.", sourceObjectiveStatus = "unverified-source-field" }
quests[13585] = { id = 13585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eid, zu beschützen", description = "Ich bin meiner Aufgabe hier so gut wie möglich nachgegangen. Sagt Malfurion, dass ich so bald wie möglich kommen werde.\n\nIch wünsche Euch viel Glück, {name}. Ich wünsche uns allen viel Glück.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm beim Auge des Vortex in Dunkelküste.", completion = "Ausgezeichnete Arbeit, {name}! Selenns Hilfe dabei, den Vortex zurückzuhalten, wird unschätzbar wertvoll sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13586] = { id = 13586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Traum", description = "Unsere Anstrengungen, die Zerstörung aufzuhalten, scheinen bisher nicht ausreichend. Ich befürchte, dass wir Hilfe jenseits dieser Welt benötigen werden.\n\nDie Schattenhammerkultisten haben in der Erdspaltergrotte östlich von hier ein Portal zum von Alpträumen geplagten Smaragdgrünen Traum erstellt. Dort halten sie einen Drachen namens Thessera gefangen.\n\nGeht durch das Alptraumportal und befreit sie. Sie wird eine mächtige Verbündete für uns sein.", sourceObjective = "Begebt Euch durch das Alptraumportal in der Erdspaltergrotte und sprecht mit Thessera.", completion = "Malfurion ruft? Ja... ich kann seine Stimme durch den Traum hindurch hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[13587] = { id = 13587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erwachende Alptraum", description = "Malfurions Worte sind wahr, <kleiner/kleine:c> {class}. Der Riss droht, Dunkelküste zu spalten und unsere Welt von der Euren zu trennen.\n\nLasst mich Euch helfen, solange ich kann, bevor der Riss die Zerstörung beider Orte beschleunigt.\n\nZuerst müsst Ihr mich von meinen Fesseln befreien; erlangt die smaragdgrüne Schriftrolle von dem Wächter, der in den Hallen unter uns zu finden ist.", sourceObjective = "Erhaltet die smaragdgrüne Schriftrolle von dem Alptraumwächter in der Erdspaltergrotte.", progress = "Habt Ihr es geschafft, {name}?", completion = "Ich danke Euch, {name}. Ihr habt mir meine Freiheit geschenkt. Nun lasst uns sehen, was ich Euch und Eurer Welt Gutes tun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13588] = { id = 13588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge aller Stürme", description = "Zwielichtreiter kreisen über dem Vortex. Ich fürchte, es ist ihre Magie, die die kataklysmischen Kräfte gegen unsere Anstrengungen sichert.\n\nFliegt mit Thessera los, um die Reiter und das Portal, aus dem sie kamen, zu zerstören.", sourceObjective = "Fliegt mit Thessera und zerstört 12 Zwielichtreiter und das Zwielichtportal.", completion = "Das Blatt hat sich gewendet, {name}. Wir sollten in der Lage sein, weiteren Schaden zu vermeiden.\n\nEs gibt aber immer noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13589] = { id = 13589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eindringlinge der Splitterspeere", description = "Als ob wir mit dem Land und den gegen uns gewandten Elementen nicht schon genug zu tun hätten, scheint es jetzt auch noch, als habe etwas die Trolle im Nordosten aufgewiegelt. Sie marschieren für den Kampf auf. Ich weiß nicht genau, was sie vorhaben, aber sie haben bereits ein paar unserer Späher angegriffen und belagern die Kultisten beim Turm von Althalaxx.\n\nWir haben einen Trupp unserer besten Schildwachen losgeschickt, um ihrem Angriff entgegenzutreten. Ich bin mir sicher, dass sie Hilfe gebrauchen könnten, also wäre es gut, wenn Ihr Euch zu den Ruinen nordöstlich von hier begebt und Euch ihnen anschließt.", sourceObjective = "Meldet Euch bei Leutnant Morra Sternenhauch bei den Ruinen von Mathystra.", completion = "Glynda hat Euch geschickt, um uns zu helfen, ja? Es war weise von ihr, das zu tun. Ich kann Hilfe sicherlich gebrauchen.\n\nIch arbeite gerade unseren Erstlingsplan aus, um ihre Ränge nach und nach zu dezimieren. Bitte helft in der Zwischenzeit Tysha und Balthule aus, wenn Ihr könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13590] = { id = 13590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An vorderster Front", description = "Ihre Streitmächte sind geschwächt, die Vorräte zerstört und die Befehlshaber zweiten Rangs sind tot. Es ist an der Zeit, den Kampf in ihr Territorium zu verlagern und ihren Anführer zu töten. Ich bin zugegebenermaßen immer noch nicht sicher, wo die plötzliche Aggression ihren Ursprung fand, aber vielleicht finden wir in ihrem Lager weitere Informationen.\n\nNehmt den Pfeil, den Balthule vorbereitet hat, und meldet Euch bei Sandrya Mondsturz im Splitterspeertal, um am Angriff teilzunehmen. Am besten sichert Ihr Euch einen Platz auf einem unserer Nachtsäbler - zu Fuß ist es zu gefährlich.", sourceObjective = "Meldet Euch bei Jägerin Sandrya Mondsturz im Splitterspeertal.", progress = "Seid gegrüßt, {class}. Habt Ihr den Pfeil?", completion = "Gut, Euch zu treffen. Ich habe von Euren Anstrengungen, uns zu helfen gehört, und ich muss zugeben, dass ich von Eurer Hilfe gegen die Trolle ein wenig beeindruckt bin. Wir befinden uns am Ende der Schlacht und ich hoffe, Ihr seid gut vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13591] = { id = 13591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Verbindungen", description = "Der Brief von Garrosh Höllschrei bestätigt den Verdacht, der während der Offensive im Splitterspeertal aufkam. Die Anwesenheit der Verlassenen bei den Ruinen des Turms, die Vorräte der Horde und ihre Vollstrecker im Kriegslager der Splitterspeere sind erst der Anfang. Garrosh selbst hat die Splitterspeere kontaktiert, um die Offensive in Richtung Lor'danel zu treiben, und es scheint, als habe er offensichtlich auch vor, von Süden vorzustoßen.\n\nGlynda Nal'Shea benötigt diese Informationen, um die Nachtelfen auf den Angriff vorbereiten zu können.", sourceObjective = "Bringt Höllschreis Brief zu Waldläuferin Glynda Nal'Shea in Lor'danel.", progress = "Ihr seid zurück! Ich habe gehört, die Schlacht ist gut verlaufen?", completion = "Nun, das sind in der Tat beunruhigende Neuigkeiten. Ich werde sofort Boten nach Eschental senden und versuchen, Verstärkung für sie aufzustellen.\n\nIch kann Euch für all Eure Hilfe in diesen schlimmen Zeiten nicht genug danken. Heldenhafte Taten wie die Euren verdienen eine Belohnung. Ich glaube, ich habe etwas, dass Euch gute Dienste leisten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[13592] = { id = 13592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldübungen eines Recken", description = "Das Turnier ist eine Gelegenheit, um Euer Können im Kampf gegen ebenbürtige Gegner auf die Probe zu stellen; doch wir dürfen nicht vergessen, dass der wahre Feind, die Geißel, nicht warten wird. Neben der Verfeinerung Eurer Fertigkeiten solltet Ihr auch Eure Bissigkeit im Kampf gegen Euren Gegner schärfen.\n\nReist in die Gegend südwestlich des Tals der Gefallenen Helden und nördlich von Corp'rethar. Die Geißel lässt dort tote Helden auferstehen und wiegelt sie gegen uns auf. Besiegt diese Diener der Geißel, macht unseren Verbündeten alle Ehre und haltet Euch bereit für den Kampf.", sourceObjective = "Sir Marcus Barlow beim Argentumturnierplatz möchte, dass Ihr 10 konvertierte Helden tötet.", completion = "Willkommen zurück von Euren Übungen, {name}. Selbst wenn wir für den Wettkampf trainieren, ist es gut, nicht zu vergessen, dass die Geißel noch immer da draußen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13593] = { id = 13593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recke von Sturmwind", description = "Seid willkommen, Champion. Ich habe schon von Euren Heldentaten gehört. Wollt Ihr der Turniersdelegation von Sturmwind beitreten?\n\nIhr werdet wie auch zuvor trainieren und die Rangleiter hinaufklettern, doch wenn man Euch zum Champion von Sturmwind ernannt hat, wird Euer Knappe die Möglichkeit haben, unser Banner in die Schlacht zu tragen.", sourceObjective = "Sprecht wieder mit Marschall Jacob Alerius, falls Ihr ein Recke von Sturmwind werden wollt.", completion = "Wir sind stolz, dass Ihr eingewilligt habt, mit uns zu trainieren und in unserem Namen anzutreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13594] = { id = 13594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergesst die Horde nicht", description = "Evenar und die anderen Schüler taugen vielleicht nicht viel für den Kampf, aber Ihr seht so aus, als ob Ihr Euch recht wacker schlagen würdet. Dem Abschaum der Horde am anderen Ende der Straße Richtung Osten in Bathrans Schlupfwinkel muss eine Lektion erteilt werden.\n\nIhr neuer Kriegsfürst Garrosh Höllschrei führt mit ihnen nichts Gutes im Schilde. Wollt Ihr ihnen Manieren beibringen?\n\nIch würde Euch begleiten, aber mein Befehl lautet, hier zu bleiben und Orendils Schüler zu beschützen – und genau das werde ich auch tun.", sourceObjective = "Tötet 10 beliebige Mitglieder der Horde in Bathrans Schlupfwinkel.", completion = "<Die Schildwache blickt Euch einen Augenblick anerkennend an.>\n\nIhr habt Eure Sache gut gemacht, {class}. Wenn die anderen Abenteurer, die wir noch zu Gesicht bekommen werden, Euch auch nur ein wenig ähneln, sollten wir diesen Krieg gegen die Orcs und ihre Horde schneller hinter uns gebracht haben, als erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13595] = { id = 13595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit ihren eigenen Waffen", description = "Diese Kreaturen... diese sogenannte Horde... Sie haben mich in meinen besten Jahren gefällt und sie ernten mein Haar für ihre finsteren Pläne.\n\nWerdet Ihr mir helfen, dem ein Ende zu bereiten, {race}?\n\nIch habe zufällig ein paar ihrer Kräuterkundigen von etwas sprechen hören, das sie Wildfeuer nannten, am Tisch entlang des Weges. Wenn Ihr die Flasche dieses widernatürlichen Zeugs nehmen und es auf meinen toten Körper im Nordosten werfen würdet, würde er verbrennen und mein Haar würde hier nicht mehr wachsen.\n\nIch bin schon tot und es ist ein kleiner Preis, um sie aufzuhalten.", sourceObjective = "Erbeutet eine Wildfeuerflasche und werft sie auf Bathrans Leichnam, um ihn zu verbrennen.", progress = "All Eure Leben sind so kurz. Warum besteht Ihr darauf, sie damit zu vergeuden, Euch gegenseitig umzubringen?", completion = "Ihr habt mir geholfen, zur Erde zurückzukehren, {name}.\n\nJetzt wird mein Haar nicht länger für diese Kreaturen sprießen. Besser noch: Ich werde umso baldiger wieder wachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13596] = { id = 13596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammerpläne", description = "Wir wissen nicht genau, welche Ziele die Schattenhammerkultisten südwestlich von hier verfolgen. Wir fürchten, sie wollen Lor'danel angreifen, allerdings können ihre Motive weitaus tiefer liegen.\n\nBegebt Euch zum Lager der Schattenhammer und besorgt ihre Pläne so schnell Ihr könnt, {name}. Uns bleibt möglicherweise nicht viel Zeit.", sourceObjective = "Erhaltet 6 Schattenhammerpläne aus dem Lager der Schattenhammer.", progress = "Habt Ihr die Pläne, {name}?", completion = "Ausgezeichnete Arbeit, {name}! Gebt mir einen Moment, um mit ihren Plänen vertraut zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13597] = { id = 13597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist des Distelbären", description = "In diesen Wäldern sind drei große Geister ansässig - der des Hirsches, der des Distelbären, und der des Mondpirschers. Diese Geister sind mächtige Verbündete, allerdings könnt Ihr Euch nur einem der Geister verschreiben.Wenn Ihr Euch mit dem großen Distelbärgeist verbünden wollt, so bringt diesen Weihrauch zu der Höhle östlich des Strudels. Meditiert vor dem großen Distelbärgeist, während Ihr den Weihrauch auf dem Boden vor Euch verbrennt und stellt Euch seiner Aufgabe, um seinen Segen zu erhalten. Kehrt zu mir zurück, wenn Ihr die Aufgabe meistern konntet.", sourceObjective = "Bewahrer Karithus hat Euch angewiesen, den Segen des großen Distelbärgeists einzuholen.", completion = "Seit ewigen Zeiten durchstreife ich diese Wälder und lebe in diesen Bergen. Durch Schnee und Feuer sah ich Zivilisationen kommen und gehen, während die Natur besteht. Nun hat sich die Erde selbst gegen uns gewandt und es ist offensichtlich, dass wir kämpfen müssen, um unser Vermächtnis zu bewahren.\n\nEuer Herz ist aufrecht und ich würde Euch als meinen Champion wählen. Wenn Euch die dicke Haut und Resistenz der Distelbären am Herzen liegt, so nehmt meine Gabe an. Ihr solltet jedoch wissen, dass Ihr danach von den anderen Geistern nicht mehr akzeptiert werdet, also entscheidet Euch weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[13598] = { id = 13598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerliche Arznei", description = "Mit Hilfe meiner Heilmagie habe ich keine Zweifel, dass Grimmklaue sich wieder erholen wird. Von den Wilderern jedoch, die ihm das zugefügt haben, kann ich nicht dasselbe sagen. Um während seiner Genesung seine Schmerzen zu lindern und seine Wunden zu behandeln, wäre allerdings eine Salbe von Nutzen.\n\nÖstlich von hier befinden sich die Ruinen von Lornesta. Dort unter den Steinen wachsen verschiedene rauchende Fliegenpilze, die in der feuchten Umgebung wunderbar gedeihen. Bringt mir ein paar der Fliegenpilze, sodass ich eine Salbe für unseren Freund zubereiten kann.", sourceObjective = "Sammelt 6 rauchende Fliegenpilze.", progress = "Grimmklaue ist ein recht hartnäckiger Kämpfer. Ich habe ein wenig Mitleid mit den Wilderern, obwohl ihre Absichten abscheulich waren.", completion = "Ihr habt meinen Dank, Jüngling. Mit dieser Salbe sollte sich Grimmklaue um einiges schneller erholen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13599] = { id = 13599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmklaues Rückkehr", description = "Nun, da der Bund geschlossen ist, liegt der Segen auf Euch. Es wird Euch das Reisen in diesen Landen sehr erleichtern.\n\nGrimmklaue hat sich vollständig erholt. Er hat sich auf den Weg nach Lor'danel gemacht, bevor ich etwas sagen konnte. Das bedeutet wohl, dass auch der Zeitpunkt Eurer Abreise gekommen ist.\n\nEs hat mich sehr gefreut, Eure Bekanntschaft zu machen. Lebt wohl, und leitet meine besten Wünsche an Volcor und Grimmklaue weiter.", sourceObjective = "Kehrt zu Volcor und Grimmklaue in Lor'danel zurück.", completion = "Ihr seid zurückgekehrt! Es ist gut, Euch wiederzusehen. Ich gehe davon aus, dass wir Euch für Grimmklaues Rückkehr zu danken haben?\n\nLeider... habe ich schlechte Neuigkeiten. Ich konnte das Gift nicht neutralisieren... ihr Zustand hat sich verschlechtert. Gershalla starb kurz nach Eurer Abreise und Volcor... Volcor starb kurz vor Eurer Rückkehr.\n\nDie sichere Rückkehr Grimmklaues hat er noch erlebt und er starb mit einem Lächeln im Gesicht. Ich wünschte nur, ich hätte mehr für ihn tun können.\n\nNun muss ich all meine Kräfte darauf richten, Shaldyn zu retten, also entschuldigt mich bitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13600] = { id = 13600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Waffe", description = "Ausgerechnet jetzt so ein Unglück!\n\nIch habe meine Turnierklinge verloren. Ich habe von Barden gehört, dass früher Reisende einer einsamen Maid Winterhyazinthen vorbeibrachten und dafür im Gegenzug etwas geschenkt bekamen. Diese Hyazinthen wachsen nur auf dem Eis, das vom Eisenwalldamm kommt, an der Nordwestgrenze des Kristallsangwalds zur Eiskrone. Pflückt ein paar der Blumen und bringt sie zum Kreis aus Laternen im Drak'Marsee in der nordöstlichen Drachenöde, nahe der Grenze zu Zul'Drak und den Grizzlyhügeln. Bittet die einsame Maid um eine würdige Klinge.", sourceObjective = "Bringt Marschall Jacob Alerius beim Argentumturnierplatz die Klinge von Drak'Mar.", progress = "Haben die Geschichten der wandernden Barden gestimmt? Habt Ihr die Klinge?", completion = "<Der Marschall nimmt die Klinge von Drak'Mar entgegen.>\n\nEine gute Waffe, perfekt ausbalanciert. Sie wird mir im nächsten Kampf gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13601] = { id = 13601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für die Flüchtlinge", description = "Bei Elune! Anscheinend haben einige derer, die wir nach dem Angriff auf das alte Auberdine totgeglaubt hatten, ein Flüchtlingslager außerhalb der Ruinen der Stadt aufgeschlagen.\n\nDie Kultisten am Lager des Schattenhammers hatten vor, kurzen Prozess mit ihnen zu machen. Bloß gut, dass Ihr ihre Stellung so erfolgreich angreifen konntet.\n\nTrefft Priesterin Alinya im Flüchtlingslager östlich des alten Auberdine tief im Süden.", sourceObjective = "Schildwache Lendra in Lor'danel möchte, dass Ihr mit Priesterin Alinya im Flüchtlingslager sprecht.", completion = "Vielen Dank, dass Ihr uns zu Hilfe eilt. Wie Ihr sehen könnt, ist die Lage der Flüchtlinge schier aussichtslos.", sourceObjectiveStatus = "unverified-source-field" }
quests[13602] = { id = 13602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naga des Strandes", description = "An der Küste im Westen lauert das Böse.\n\nDer Zoramstrand ist die Ruhestätte der verfluchten Stadt Zoram, die während der Großen Zerschlagung zerstört wurde und im Meer versank. Dort liegt sie seit langer Zeit, verloren für die Nachtelfen. Verloren und beinahe vergessen.\n\nJetzt sind die Naga zurückgekehrt und wir wissen nicht aus welchen Gründen. Aber Gründe spielen keine große Rolle. Wir müssen diese Feinde vernichten und sie zurück in ihre Tiefen zwingen.", sourceObjective = "Tötet 15 beliebige Naga der Rächerflossen am Zoramstrand.", completion = "Gut gemacht, {name}. Eure Handlungen gegen die Naga am Zoramstrand waren rühmenswert.\n\nIch weiß, dass diese Heldentat nicht leicht zu vollbringen war, denn die Stärke und Arglist der Naga sind den Nachtelfen wohl bekannt. Wir wissen das, denn sie und wir haben eine gemeinsame Vergangenheit.\n\nDie Naga sind verfluchte Hochgeborene der Nachtelfen. Vor zehntausend Jahren schloss Königin Azshara in ihrer Verzweiflung einen Pakt mit den Alten Göttern, damit die Überlebenden ihres Volkes nicht in einem nassen Grab enden.\n\nDie Naga sind das Ergebnis dieses Paktes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13603] = { id = 13603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Guter, ehrlicher, fein geschliffener Stahl mag nicht immer ausreichen, um den Sieg zu sichern. Die anderen Kämpfer benutzen verzauberte Klingen und ich bin nun ins Hintertreffen geraten - aber noch ist nicht alles verloren.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Marschall Jacob Alerius beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "Also waren die Geschichten wirklich wahr? Dies ist eine feine Klinge, die mir ohne Zweifel gute Dienste im Turnier leisten wird. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13604] = { id = 13604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenscheibe des Archivums", description = "Diese Platinscheibe ist überraschend symmetrisch und frei von jedweden Kratzern und Unebenheiten. An ihrer Seite steht in auffallenden Runen eingeprägt das Wort \"ARCHIVUM\".\n\nIn Ulduar muss es eine Vorrichtung geben, mit welcher sich die Informationen auf der Scheibe lesen lassen.", sourceObjective = "Bringt die Datenscheibe des Archivums zur Archivumkonsole in Ulduar.", progress = "Die Konsole surrt vor Energie, als sich der runde Aufnahmebehälter öffnet.", completion = "Die Platinscheibe passt perfekt in die Konsole. Sie fängt an, sich zu drehen. Weiße Lichtstrahlen scheinen die darauf befindlichen Informationen abzutasten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13605] = { id = 13605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Flüchtling", description = "Es gab ein riesiges Erdbeben und alles wurde dunkel. Meine nächste Erinnerung ist, wie ich hier als Gefangene aufwachte. Der ganze Ort ist voll von Elementaren!\n\nIch hoffe, es geht allen gut. Dieser Schattenhammerabschaum hat besser keinem meiner Freunde Leid zugefügt!\n\nSchnell, {class}, benutzt etwas Scharfes, um das Schloss hier zu öffnen. Zusammen sollten wir es bis zum Flüchtlingslager schaffen.", sourceObjective = "Begleitet Archäologin Hollee in Sicherheit.", completion = "Ah, Ihr seid der gute Mann, der meine Hollee gerettet hat!\n\nNun, ich habe für Euch eine passende Belohnung. Wir können Euch nicht genug dafür danken, sie in Sicherheit gebracht zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13606] = { id = 13606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Siegel", description = "Ich fürchte, Freyas Siegel zu erlangen, wird eine der schwierigeren Aufgaben sein.\n\nLaut dem Archivum ist die Essenz des Siegels mit ihren drei Dienern verbunden, den Ältesten Hellblatt, Eisenast und Steinrinde. Sollte einer der Ältesten zu Schaden kommen, ist die Unversehrtheit des Siegels gefährdet.\n\nDie Ältesten zu verschonen bedeutet jedoch, dass Freya mehr Macht haben wird, wenn Ihr Euch ihr stellen werdet.\n\nWas soll ich sagen, {name}, das ist eine ganz schöne Zwickmühle, in der wir da stecken.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Freyas Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Freyas Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Freyas Siegel, {name}? Habt Ihr es?", completion = "Verdammt gute Arbeit, {name}. Wir sind unserem Ziel, Azeroth zu retten, einen Schritt näher!", sourceObjectiveStatus = "unverified-source-field" }
quests[13607] = { id = 13607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Himmlische Planetarium", description = "Hört mal, <Kumpel/Mädel>! Das Schicksal von Azeroth steht hier auf dem Spiel.\n\nUnsere einzige Chance ist es, rechtzeitig das Himmlische Planetarium zu erreichen, um diesen Algalon zu finden und ihn davon abzuhalten, irgendwelche Nachrichten an seine titanischen Herren abzusetzen.\n\nFindet das Himmlische Planetarium und beschafft so viele Informationen wie möglich. Uns könnte noch immer ein wenig Zeit bleiben, uns auf Algalons Ankunft vorzubereiten.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr den Eingang zum Himmlischen Planetarium findet.", progress = "Habt Ihr ihn gefunden, {name}?", completion = "Es ist verschlossen? War ja klar!\n\nDann wollen wir doch mal sehen, was für Informationen wir aus diesem Müllhaufen rausholen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[13609] = { id = 13609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Siegel", description = "Es wird nicht einfach sein, Hodirs Siegel zu beschaffen. Ihr müsst nämlich nicht nur Hodir selbst vernichten, sondern es auch noch tun, bevor er die Truhe zerstört, in der es sich befindet!\n\nSchaut Euch die Archivumkonsole an, falls Ihr weitere Informationen benötigt. Das Ding umfasst mehr Wissen als alle Bibliotheken der Welt zusammen!", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Hodirs Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Hodirs Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Habt Ihr das Siegel, {name}?", completion = "Ihr habt es geschafft! Ich weiß nicht wie, aber Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[13610] = { id = 13610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thorims Siegel", description = "Thorim ist nicht er selbst, {name}. Er ist das Opfer einer dunklen Macht geworden, die ihn nun steuert.\n\nDas Opfer von etwas Bösem, das ihm die Illusion vorspielt, seine verstorbene Frau Sif zu sein.\n\nIhr dürft nicht zulassen, dass der Zauber dieses Betrügers ihn überwältigt. Denn sollte es so kommen, wird das Wissen um die Lage des Siegels für immer verloren sein!\n\nIhr müsst ihn zur Vernunft bringen und zwar schnell.\n\nWie immer wird Euch die Archivumkonsole mit allen schmutzigen Details versorgen... selbst mit denen, die Euch nicht gefallen.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Thorims Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Thorims Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Nun, {name}? Habt Ihr's?", completion = "Ihr werdet wohl nie aufhören, mich zu beeindrucken, {name}.\n\nIhr und ich sollten mal ein Bierchen trinken gehen, nachdem wir mit all dem hier durch sind. Mein Wort drauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[13611] = { id = 13611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimirons Siegel", description = "Mimiron ist ein ganz Schlauer. Sein gesamter Sitz ist mit einer Art Selbstzerstörungsmechanismus ausgestattet.\n\nUnglücklicherweise wird es ein Wettlauf gegen die Zeit werden, sein Siegel zu bekommen. Befragt die Archivumkonsole, um Näheres darüber zu erfahren, falls nötig.", sourceObjective = "Ausgrabungsleiter Doren im Archivum in Ulduar möchte, dass Ihr in den Besitz von Mimirons Siegel gelangt.\n\nUm mehr darüber herauszufinden, wie Ihr Mimirons Siegel erlangen könnt, solltet Ihr die Archivumkonsole zu Rate ziehen.", progress = "Konntet Ihr das Siegel an Euch bringen, {name}?", completion = "Das muss man Euch wirklich lassen, {name}. Unsere Chancen stehen vielleicht nicht zum Besten, aber wenn Ihr mit anpackt fühle ich mich gleich viel besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[13612] = { id = 13612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Mor'shan", description = "Lok'tar, {race}!\n\nDer Feldzug hat endlich begonnen! Bald wird sich ganz Eschental in den Händen der Horde befinden.\n\nWie wir erwartet haben, zwingt unser Angriff den Feind dazu, unsere Verteidigung an jeder erdenklichen Stelle auf die Probe zu stellen.\n\nHier in Mor'shan wurde ihre Angriffskraft geschwächt! Aber die Schlinge zieht sich immer enger zu. Sie haben keine Wahl, als uns hier weiter unter Druck zu setzen.\n\nErkundet die Umgebung, {class}. Sucht nach den Überlebenden der Nachtelfen und vernichtet sie, bevor sie sich zu einem neuen Angriff sammeln können!", sourceObjective = "Kadrak beim Schutzwall von Mor'shan will, dass Ihr 5 Scharmützler des Eschentals und 5 Bogenschützen des Eschentals tötet.", progress = "War Eure Jagd erfolgreich, {race}?", completion = "Gute Arbeit, {class}!\n\nEure Bemühungen werden uns dabei helfen, die Feinde auf Trab zu halten, während wir mit unseren Streitkräften über das Land herfallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13613] = { id = 13613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Gefallenen", description = "Unsere Streitkräfte schlagen sich großartig, {class}.\n\nAber so erfreulich das auch ist, jemand muss sich noch um die Verwundeten kümmern, von denen sich noch viele auf dem Schlachtfeld befinden.\n\nIch habe eine Salbe angerührt, die den Verwundeten genug Kraft geben sollte, um zur weiteren Behandlung zum Schutzwall zurückzukehren. Bitte verabreicht sie jedem, der sie benötigt, bevor sie für unsere Sache verloren sind.", sourceObjective = "Verwendet die heilkräftige Salbe bei 5 verletzten Verteidigern von Mor'shan.", completion = "Habt Dank, {race}. Ich werde den Dienst, den Ihr der Horde geleistet habt, in meinem Bericht erwähnen.\n\nDiese Truppen werden in kürzester Zeit wieder kampfbereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13614] = { id = 13614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algalon", description = "Ihr habt es wirklich geschafft, {name}. Bringt die Siegel zur Archivumkonsole und seht zu, ob Ihr Zugang zum Himmlischen Planetarium erhaltet.\n\nIhr beeilt Euch besser, <Kumpel/Mädchen>. Die Zeit drängt.", sourceObjective = "Bringt die Siegel der Wächter zur Archivumkonsole in Ulduar.", progress = "Die gleißenden Lichter der Konsole scannen mehrmals die Glasoberfläche, gerade so, als ob eine Form von Datenübermittlung erwartet würde.", completion = "Verifizierungsprozess läuft.\n\nZugang zum himmlischen Planetarium gewährt. Bitte Schlüssel entnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13615] = { id = 13615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leere Köcher", description = "Seid gegrüßt, {class}, und willkommen am Schutzwall.\n\nEs mag hier etwas chaotisch zugehen, aber seid unbesorgt. Kadrak hat diesen Stützpunkt gut abgeschottet. Nicht ein einziger Elf konnte unsere Reihen durchbrechen!\n\nWo Ihr schon mal hier seid... Ich erwarte eine neue Versorgungslieferung aus Orgrimmar. Sie müsste jeden Tag eintreffen, aber unseren Wachmännern gehen bald die Pfeile aus.\n\nBringt mir jeden, den Ihr findet, und Ihr werdet es nicht bereuen.", sourceObjective = "Truun im Schutzwall von Mor'shan verlangt von Euch, 10 brauchbare Pfeile in der Umgebung des Himmelssturzsees einzusammeln.", progress = "Habt Ihr die Pfeile, die wir brauchen, {class}?", completion = "Gute Arbeit, {class}.\n\nDamit sollten wir bis zum Eintreffen der nächsten Lieferung durchhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13616] = { id = 13616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Winters Schneide", description = "Verflucht soll dieser Todesritter dafür sein, mein Schwert zerbrochen zu haben!\n\nIm südlichen Teil des Kristallsangwalds, über dem Ausgang der Kristallschlucht, werdet Ihr Lord Immerflamm finden. Tötet ihn und entnehmt seinen Überresten die ewig brennende Glut.\n\nBringt sie zur Mitte des Winterhauchsees im Norden des Heulenden Fjords und befreit damit die in Eis eingeschlossene Maid. Sie ist die Wächterin eines uralten Schwerts und wird es einem jeden überreichen, der sie befreit.\n\nZeigt, was Ihr wert seid, und verdient Euch die Waffe, die sie nun schon so lange bewacht, {name}.", sourceObjective = "Marschall Jacob Alerius beim Argentumturnierplatz möchte, dass Ihr ihm die Winterschneide beschafft.", progress = "Habt Ihr die Klinge errungen, nach der ich suche?", completion = "Die Klinge ist so wundervoll, wie die Geschichten es verheißen. Es gibt wohl kaum einen triftigen Grund, die Reparaturen an einem gewöhnlichen Schwert abzuschließen. Die Winterschneide ist ihm bei weitem überlegen und ich werde sie in Zukunft tragen. Ihr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13617] = { id = 13617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Westen zum Strand", description = "{name}, ein Freund von mir könnte Eure speziellen Fähigkeiten gut gebrauchen. Sein Name ist Talen und er ist so eine Art Archäologe. Neuerdings fasziniert ihn der Untergang der alten Stadt Zoram mit ihren Schätzen.\n\nWenn Ihr ihm zur Hand gehen wollt, findet Ihr ihn im Stützpunkt an der Grotte den Weg entlang nach Westen.", sourceObjective = "Sprecht mit Talen am Stützpunkt an der Grotte im Eschental.", completion = "Hallo, {class}.\n\nWie war das? Ihr sagt, Shyela schickt Euch?\n\n\n\nSehr gut, fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[13618] = { id = 13618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Gorat!", description = "Gorat ist einer der fähigsten Assassinen der Horde.\n\nDie bloße Erwähnung seines Namens erfüllt die Herzen unserer Gegner von der Allianz mit Angst.\n\nEr ist zuverlässig, absolut loyal, und – bisher – pünktlich.\n\nEtwas stimmt nicht, {class}.\n\nGorats Aufgabe bestand darin, den Elf zu finden und zu töten, der für diesen Angriff auf den Schutzwall verantwortlich ist.\n\nEr sollte sich irgendwo in der Gegend um den Himmelssturzsee herum aufhalten.\n\nFindet ihn!", sourceObjective = "Kadrak am Schutzwall von Mor'shan will, dass Ihr die Gegend um den Himmelssturzsee herum nach Gorat absucht.", completion = "Hört gut zu, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[13619] = { id = 13619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlussbericht", description = "<Gorat hustet schwer, als er versucht, zu sprechen.>\n\nEs war... ein Hinterhalt...\n\nWir waren... auf dem Rückweg zum Schutzwall. Die anderen... alle sind... verloren...\n\nWir haben... ihren Anführer entdeckt... \n\n<Gorat füllt sorgfältig eine Phiole mit dem Blut, das aus einer seiner Wunden quillt.>\n\nMeine Männer... müssen gerächt werden... Bringt dies... zu Kadrak...\n\nEr wird wissen, was zu tun ist...\n\n<Gorat stirbt.>", sourceObjective = "Gorat will, dass Ihr die Phiole mit Gorats Blut zu Kadrak beim Schutzwall von Mor'shan bringt.", progress = "Habt Ihr Gorat gefunden, {class}?", completion = "<Kadrak hört aufmerksam zu, während Ihr ihm Gorats letzte Worte übermittelt.>\n\nEs ist also so, wie ich befürchtet hatte. Möge er in Frieden ruhen – aber jetzt noch nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[13620] = { id = 13620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Dinah, sofort!", description = "Vielleicht war niemand der Horde so treu ergeben wie Gorat. Bisher ist er noch bei keiner Mission gescheitert, und es scheint, als ob er es nicht zulassen wollte, dass dies seine erste wird.\n\nGorat hat Euch diese Phiole zu einem bestimmten Zweck gegeben. Dinah ist die Tochter eines ehrwürdigen Schamanen und sie ist mächtiger, als es erscheint. Bringt die Phiole zu ihr und hofft, dass wir nicht zu spät kommen.", sourceObjective = "Kadrak möchte, dass Ihr die Phiole mit Gorats Blut zu Dinah am Schutzwall von Mor'shan bringt.", progress = "Was habt Ihr da, {race}?", completion = "Sehen wir uns das mal an, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13621] = { id = 13621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorats Vergeltung", description = "Das Glück ist uns heute hold, {race}.\n\nGorats Blut war noch frisch genug, sodass ich ein besonderes Ritual durchführen konnte, das mir als Kind beigebracht wurde.\n\nVerwendet dieses angereicherte Blut auf Gorats Leichnam, um seinen dort noch immer wandelnden Geist zu beschwören.\n\nErweist ihm diesen letzten Dienst. Dann kehrt hierher zurück und berichtet Kadrak.\n\nMögen die Geister Euch schützen.", sourceObjective = "Dinah will, dass Ihr Gorats machterfülltes Blut auf Gorats Leichnam anwendet und dann Hauptmann Elendilad vernichtet.", completion = "Gut gemacht, {race}.\n\nDer Hauptmann der Elfen ist tot und die Seele eines unserer geliebten Brüder ruht nun in Frieden.\n\nIch werde die Kunde von Euren Taten an meine Vorgesetzten in Orgrimmar weiterleiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13622] = { id = 13622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Geschichten", description = "Die Stücke lassen sich zu einem eleganten Hammer zusammenfügen. Seine Bauweise erweckt den Eindruck, zumindest teilweise von titanischer Natur zu sein.\n\nWomöglich könnte man über die Konsole im Archivum mehr über dieses Artefakt erfahren.", sourceObjective = "Bringt die zerschmetterten Fragmente von Val'anyr zur Archivumkonsole im Archivum in Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13623] = { id = 13623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Orendil", description = "Rasch, {name}. Ich werde das Bathranshaar in diesen Beutel füllen, aber Ihr müsst es an meinen Meister Orendil Rundblatt liefern. Ihr findet ihn in Maestras Posten, einfach Richtung Süden die Straße entlang auf der linken Seite.\n\nAber seht Euch vor, wir haben Nachricht erhalten, dass der Posten von der Horde angegriffen wird!", sourceObjective = "Bringt den Beutel voll Bathranshaar zu Orendil Rundblatt in Maestras Posten im Eschental.", progress = "Ihr seid mutig, unter diesen Umständen hierher zu kommen.\n\nWie lautet Euer Anliegen, Fremder?", completion = "Also hatte Evenar Erfolg. Um es genauer zu sagen, IHR hattet Erfolg.\n\nIch kann Euch nicht genug danken, {class}, aber diese Blätter müssen noch weiter verarbeitet werden, bevor sie als Heilmittel gegen das Unheil dienen können, welches das Kind Relara dahinsiechen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13624] = { id = 13624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Staffel nur für Euch", description = "Ich gehe davon aus, Ihr seid hier, um zu helfen, {class}. Die Lage ist so schlimm, wie sie erscheint. Um es auf den Punkt zu bringen: Wir verlieren!\n\nMeine Mädchen und ich sind die letzte Verteidigungslinie gegen die Horde, aber wir werden hier nicht verschwinden, ohne den Kampf zu ihnen zu tragen. Bereit für eine Herausforderung?\n\nIch habe eine kleine Staffel von Schildwachen, die ich Euch unterstellen könnte. Bringt sie in ihre Nähe und ich bin mir sicher, dass ihre magischen Pfeile diese Räuber und Eindringlinge vernichten werden.\n\nSprecht mich wieder an, falls Ihr Ersatz benötigt.", sourceObjective = "Verwendet eine Staffel der Schildwachen aus Maestras Posten, um 3 Zerstörer des Eschentals und 10 Eindringlinge der Horde zu vernichten.", completion = "Einer meiner Späher in den Wäldern hat mir von Euch berichtet, aber ich hatte ja keine Ahnung, wozu Ihr wirklich in der Lage seid!\n\nHabt Dank, {name}. Durch das, was ihr erreicht habt, hat sich das Blatt gewendet. Ich habe keine Zweifel mehr, dass wir sie bis zum Tagesende besiegt haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13625] = { id = 13625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reitgrundlagen", description = "Die meisten Wettkämpfe des Turniers verlangen von den Wettstreitern, dass sie den Kampf auf einem Reittier beherrschen. Um Euch mit dem berittenen Kampf vertraut zu machen, haben wir überall im nördlichen Teil des Turnierplatzes Trainingsattrappen aufgestellt.\n\nGeht zu den angebundenen Reittieren außerhalb des Pavillons, nehmt Eure Lanze und steigt auf das Streitross der Quel'dorei. Macht Euch mit den verfügbaren Taktiken vertraut und besiegt anschließend die drei verschiedenen Arten von Trainingsattrappen.", sourceObjective = "Trefft ein Nahkampfziel fünfmal mit der Fähigkeit \"Zustoßen\" und wendet die Fähigkeit \"Schildbrecher\" auf 2 ungeschützte Distanzziele sowie die Fähigkeit \"Sturmangriff\" auf 2 ungeschützte Sturmangriffsziele an. Kehrt anschließend zu Späherin Shalyndria beim Argentumturnierplatz zurück.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", completion = "Gut gemacht, {name}. Für diejenigen, die den Kampf zu Boden gewohnt sind, ist es oft sehr schwer, den berittenen Kampf zu erlernen. Ich habe keine Zweifel daran, dass Ihr Euch mit entsprechender Übung weiterhin verbessern werdet - was weitaus mehr ist als das, was ich von manch anderen Kriegern behaupten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13626] = { id = 13626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Gefallenen zu Ehren", description = "Es gab hier zwei Menschen: Feero Eisenhand und Delgren der Läuterer. Sie waren Mitglieder einer heiligen Organisation, die als Argentumdämmerung bekannt ist. Beide fielen bei der Verteidigung des Postens gegen den ersten Angriff der Horde.\n\nIch werde Euch meinen magischen Umhang borgen. Es ist ein Geschenk von Cenarius. Mit seiner Hilfe kann ich mich unsichtbar machen.\n\nFindet die beiden Leichname und spürt Feeros Hammer sowie Delgrens Gebetsbuch auf. Feeros Leichnam ist im Hof und Delgren liegt auf der Spitze des Turms.\n\nSeht Euch vor, denn der Hexenmeister dort oben wird Euch sehen können.", sourceObjective = "Holt Feeros heiligen Hammer und das Gebetsbuch des Läuterers zurück.", progress = "Unsere Verluste sind niederschmetternd.", completion = "Ich freue mich nicht sonderlich darauf, den Brief an die Botschaft der Argentumdämmerung in Darnassus zu schreiben. Zumindest sind wir in der Lage, die meisten ihrer Besitztümer zu den Angehörigen zurückzuschicken.\n\nIch kann Euch nicht genug für Euren Mut danken, {name}. Bitte nehmt dies im Namen des Postens entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13627] = { id = 13627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie die Axt im Walde", description = "Kommt näher. Nein, nicht zu nah. Wir wollen doch keinen Grund für unnötige Verdächtigungen geben, nicht wahr?\n\nDiese Turnierhalle benötigt mehr Holz, als wir auf Lager haben, und die Kosten für einen Ferntransport von den Grizzlyhügeln werde ich auf keinen Fall zahlen. Im Westen des Kristallsangwaldes, in der Nähe des Großen Baumes, wachsen etliche junge Kristallsangeichen. Das wäre genau das Holz, das wir zum Bauen und als Gerüstmaterial bräuchten. Nehmt dieses Beil, schlagt einige Bäume und haut daraus ein paar Hölzer. Aber lasst Euch dabei bloß nicht erwischen!", sourceObjective = "Bringt 12 grob gehauene Bauhölzer zu Stumpi Sprengbolz beim Argentumturnierplatz.", progress = "Habt Ihr die \"Waren\", von denen wir gesprochen hatten?", completion = "Das ist exzellentes Bauholz und der Preis stimmt auch! Besser noch, diese angestaubten Typen vom Argentumkreuzzug werden's nie erfahren. Sie bekommen ihre heißgeliebte Turnierhalle und ich bekomme meinen Bonus für den schnellen Bauabschluß. Wenn das mal kein Gewinn für beide Seiten ist, dann weiß ich auch nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[13628] = { id = 13628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut Holz", description = "Kadrak hat gerade neue Befehle für unsere Truppen erhalten. Mir ist zu Ohren gekommen, dass wir mit dem Angriff auf Eschental beginnen!\n\nIch habe viel zu wenig Vorräte, um einen Angriff zu unterhalten, und meine Lieferung aus Orgrimmar ist noch nicht eingetroffen.\n\nIch bin gezwungen zu improvisieren und könnte Eure Hilfe gebrauchen, {class}.\n\nSprecht mit Kadrak und fragt ihn nach den Zügeln von Brutusk. Der Kodo wird Euch zum Lager des Kriegshymnenklans tragen. Sobald Ihr dort seid, sucht nach Gorka und bittet sie, Euch mit Baumstämmen zu beladen.", sourceObjective = "Truun will, dass Ihr mit Brutusk zum Lager des Kriegshymnenklans reitet.\n\nSprecht mit Kadrak, um Kadraks Zügel zu erhalten und Brutusk reiten zu können.", completion = "Willkommen, {class}. Es ist schön, zu sehen, dass die Straße zum Schutzwall von Mor'shan frei bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13629] = { id = 13629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Val'anyr, Hammer der Uralten Könige", description = "Die Archivumkonsole hat eine Möglichkeit angedeutet, wie die Fragmente von Val'anyr wieder zusammengefügt werden können: Ihr müsst die Fragmente ins Innere der körperlichen Form des Wesens namens Yogg-Saron bekommen.\n\nEs mag vielleicht aussichtslos klingen, doch Ihr denkt, dass ein Artefakt von solcher Macht das Risiko wert sein könnte.", sourceObjective = "Werft die zerschmetterten Teile von Val'anyr in Yogg-Sarons Schlund, während er den Zauber 'Ohrenbetäubendes Gebrüll' wirkt, und vernichtet ihn, um den neugeschmiedeten Hammer der Uralten Könige zu erhalten.\n\nDies kann nur auf dem Schwierigkeitsgrad \"Heroisch\" beendet werden und nur dann, wenn Ihr von maximal drei Wächtern von Ulduar unterstützt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13630] = { id = 13630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus diesem Grund", description = "Die Furbolgs sind von ihren Anhöhen herabgestiegen und haben die Ruinen von Ordil'Aran im Norden überrannt. Ich vermute, dass sie das getan haben, weil sie von etwas angezogen wurden, was die toten Kultisten dort entdeckt haben: drei Mondsteine.\n\nLiladris Mondbach wird Euch raten, wie Ihr mit den Furbolgs auf eine direktere Weise fertigwerdet und ich werde ihr nicht widersprechen. Aber ich würde Euch darum bitten, Euch zu den Ruinen zu begeben und die Mondsteine zu deaktivieren.", sourceObjective = "Deaktiviert den blauen, den grünen und den roten Mondstein.", completion = "Habt Dank, {name}.\n\nJetzt, wo die Mondsteine von Ordil'Aran deaktiviert sind, brauchen wir uns hier nicht um weitere Überfälle der Furbolgs zu sorgen.\n\nNichtsdestotrotz sind meine Späher mit verstörenden Neuigkeiten aus dem Dorf der Furbolgs zurückgekehrt. Dort braut sich etwas zusammen.\n\nIch frage mich, ob ich Euch darum bitten kann, für mich eine Warnung nach Astranaar zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13631] = { id = 13631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ende gut, alles gut", description = "Wir sollten uns jetzt besser beeilen, {name}. Wir müssen den Antwortcode von Dalaran aus übermitteln.\n\nBringt ihn zu Rhonin. Ich treffe Euch dort.", sourceObjective = "Überbringt Rhonin in Dalaran den Antwortcode Alpha.", progress = "Seid Ihr soweit, {name}?", completion = "Ihr seid hier. Lasst uns hoffen, dass das hier klappt. Um unser aller willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13632] = { id = 13632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Fronten", description = "Die Mondpriesterin hat einen Plan, der sicherstellen soll, dass keine weiteren Furbolgs aus dem Hochland herabsteigen. Ich mache mir mehr Sorgen um diejenigen, die bereits bei den Ruinen sind und von denen einige sich direkt vor dem Posten zusammenrotten.\n\nSo unangenehm es auch sein mag, ich muss Euch bitten, Euch nach Norden in die Ruinen von Ordil'Aran zu begeben und die Furbolgs zu vernichten. Wir können nicht an zwei Fronten gleichzeitig kämpfen!\n\nHabt Dank, {class}.", sourceObjective = "Tötet 10 beliebige Furbolgs in den Ruinen von Ordil'Aran.", completion = "Wir stehen in Eurer Schuld, {class}. Wenn ich Eines über die Furbolgs weiß, dann dies: Sie schätzen es nicht, blutige Nasen zu bekommen.\n\nEs wird nicht lange dauern, bevor sie den Schwanz einziehen und in ihr Dorf zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13633] = { id = 13633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Westfall?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, der Cooperfamilie in Westfall zu entstammen. Würdet Ihr Euch aufmachen und den Wohnsitz der Familie in Mondbruch in Westfall aufsuchen? Vielleicht lässt sich dort ein Beweis für seine Geschichte finden.", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen, solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13634] = { id = 13634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Ritter von Silberwald?", description = "Zweifellos habt Ihr bereits die beunruhigenden Gerüchte gehört, die einen Teilnehmer betreffen, der der schwarze Ritter genannt wird. Es heißt, dass jeder Reiter, der sich ihm im Kampf stellen musste, ein vorzeitiges Ende gefunden hätte.\n\nNatürlich haben wir nichts in der Hand, aber es kann ja nicht schaden, sich den Hintergrund dieses Ritters mal näher anzusehen.\n\nEr behauptet, aus Valgans Feld im Silberwald zu stammen, einem kleinen Gehöft an der westlichen Küste des Lordameresees. Könntet Ihr dem Hof einen Besuch abstatten und mich wissen lassen, ob seine Geschichte der Wahrheit entspricht?", sourceObjective = "Überprüft die Angaben des Schwarzen Ritters und kehrt mit den Informationen zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz zurück.", progress = "Habt Ihr etwas über die Herkunft des Schwarzen Ritters herausfinden können?", completion = "Ihr meint also, an der Geschichte des Schwarzen Ritters wäre etwas faul? Sehr verdächtig. Ohne jede Ehre im besten Falle und im schlimmsten ein blutdürstiger Mörder. Trotzdem können wir ihn nicht zur Rede stellen solange wir nicht wissen, dass er in die Morde verwickelt war.\n\nTut nichts, was seinen Verdacht erregen könnte, {name}. Diskretion wird uns von Nutzen sein, während wir unsere Nachforschungen vorantreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13635] = { id = 13635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Statusbericht des südlichen Tors", description = "Wir müssen den Gebirgsjägern im Tal der Könige einen Statusbericht zukommen lassen.\n\nIch gehe davon aus, dass Ihr sowieso in diese Richtung wolltet - könntet Ihr den Bericht für mich abliefern? Nehmt den Tunnel östlich von hier und meldet Euch beim Wachposten. Der Bericht muss direkt zu Hauptmann Rugelfuß.", sourceObjective = "Liefert den Statusbericht von Pilot Hammerfuß bei Hauptmann Rugelfuß im Tal der Könige ab.", progress = "Was führt Euch hier her?", completion = "Der Statusbericht des südlichen Tors? Ausgezeichnet. Ich warte schon seit Längerem auf Neuigkeiten von dort.\n\nEs finden sich immer mehr Troggs auf den Hügeln und ich fürchte, die Außenposten dort werden als Erstes von den Aggressionen zu spüren bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13636] = { id = 13636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle für Sturmlanze", description = "Gebirgsjäger Sturmlanze muss neue Befehle bei seinem Posten der Station Algaz erhalten. Ihr stört Euch doch nicht daran, sie ihm zu bringen? Folgt der Straße bis ihr nordöstlich von hier den Bunker seht.\n\nIhr könnt ihm auch gerne bei seinen Aufgaben helfen. Natürlich würde ich Euch dafür entsprechend belohnen.", sourceObjective = "Bringt die Befehle für Sturmlanze zu Gebirgsjäger Sturmlanze in der Station Algaz.", completion = "Befehle! Mal sehen, was es zu tun gibt... ha! Mit den Rattenmenschen soll ich mich herumschlagen. Die sind hier eh schon überall, also macht das auch keinen Unterschied mehr.\n\nWollt Ihr helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[13637] = { id = 13637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widdertransport", description = "Die Gebirgsjäger im Südtoraußenposten haben eine Widderlieferung für ihre Patrouillen angefordert. Ich hätte nicht gedacht, dass wir Kräfte erübrigen können, aber dank Euch können wir ihnen wenigstens einen zukommen lassen.\n\nHättet Ihr etwas dagegen, ihn für mich bei Soldat Hammerfall abzugeben? Lasst mich wissen, wenn Ihr bereit zum Aufbruch seid." }
quests[13638] = { id = 13638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gefangene Gebirgsjäger", description = "Ihr habt Euch als mehr als fähig im Kampf erwiesen. Nun habe ich eine etwas wichtigere Angelegenheit für Euch.\n\nEiner meiner Männer, Gebirgsjäger Kieselwut, wurde von den Troggs gefangen genommen, die wir am südlichen Teil der Berge bekämpfen. Naja, er gab mehr auf, als dass er wirklich gefangen genommen wurde, aber das Resultat ist das gleiche. Er wollte wohl von innen herausfinden, wer ihr Anführer ist.\n\nIhr müsst ihn da rausholen. Sie halten ihn wahrscheinlich in der Nähe der höheren Höhlen tief im Berg.", sourceObjective = "Hauptamnn Rugelfuß in Thelsamar möchte, dass Ihr den Gebirgsjäger Kieselwut findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13639] = { id = 13639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Ausgrabungsstätte", description = "Eisenband hat südöstlich von hier eine Ausgrabungsstätte, für die er ordentlich Sprengstoff von der Liga geschickt bekommen hat. Huldar, Miran und Saean sind gerade mit der letzten Ladung los und können wahrscheinlich Hilfe gebrauchen.\n\nWeit sind sie sicher noch nicht gekommen, so stark wie sie sind. Mit vollen Fässern ist man nicht so schnell.\n\nSie haben den normalen Weg zur Ausgrabungsstätte eingeschlagen, durch das Südtor und am Loch vorbei. Versucht, sie einzuholen und ihnen zu helfen, ja?", sourceObjective = "Findet Huldar, Miran und Saean.", completion = "Ha, es braucht mehr als einen Hinterhalt der Dunkeleisenzwerge, um uns aufzuhalten!\n\nAber Saean... ich hätte nie gedacht, dass er ein Sympathisant ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich nur nicht richtig aufgepasst.\n\nIch werde mich später darüber sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13640] = { id = 13640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Managerqualitäten", description = "Truun braucht Holz, wie? Normalerweise könnte ich ihm welches liefern, aber nicht heute.\n\nDurch die ständigen Angriffe der Elfen ist das Holzschlagen zu einem gefährlichen Unterfangen geworden. Meine Peons sträuben sich und wagen sich nicht in den Wald.\n\nIhr wollt Holz? Dann überzeugt die Peons, ihre Arbeit wieder aufzunehmen.\n\nUnd sorgt dafür, dass ihnen nichts zustößt! Ich kann es mir nicht leisten, noch weitere zu verlieren!", sourceObjective = "Überzeugt demoralisierte Peons, wieder an die Arbeit zu gehen und 5 Stück frisch gespaltenes Holz zu sammeln.", progress = "Habt Ihr das Holz bekommen, das Ihr benötigt?", completion = "Es scheint, Ihr habt das eine Problem gelöst, nur um vor einem neuen zu stehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13641] = { id = 13641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seherkristall", description = "Jetzt, da wir wissen, dass der Schwarze Ritter nicht die Wahrheit spricht, müssen wir einen Weg finden, seine Verbindung zu den toten Rittern nachzuweisen.\n\nIch kenne einen Weg um die Wahrheit über ihren Tod aufzudecken, doch er benötigt ein seltenes Material. Wir müssen einen Seherkristall auftreiben, der nur bei den unbändigen Sehern gefunden werden kann, die sich in der Nähe der Nachtelfenruinen in den Trostlosen Wäldern im Zentrum des Kristallsangwaldes versammeln. Findet einen dieser Seher, {name}, und bringt mir die Kristalle, die er bei sich trägt.", sourceObjective = "Bringt einen Seherkristall zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr einen Seherkristall finden können?", completion = "Der wird vollkommen genügen. Nun bleibt nur noch, ihn mit der Macht des Lichtes zu erfüllen, sodass er die Fähigkeit erhält, die unter Lügen verborgene Wahrheit zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13642] = { id = 13642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Licht getaucht", description = "Das Gebräu ist noch nicht ganz fertig. Es muss noch in das Licht von Elune getaucht werden, bevor wir auch nur daran denken können, es dem Kind zu geben.\n\nIm Westen am Falathimsee ist uns ein Ort bekannt, wo das Mondlicht der Göttin fortwährend auf die Erde fällt - bei Tag und bei Nacht. Bitte, {name}, um Relaras Willen flehe ich Euch an: Nehmt das Gebräu und badet es in Elunes Strahlen.\n\nAber hütet Euch! Seltsame Dinge gehen im Gebiet um den See vor sich und ich befürchte, dass es nicht mehr sicher ist, dorthin zu gehen.", sourceObjective = "Stellt ein eingetauchtes Gebräu her.", progress = "Hattet Ihr Schwierigkeiten, zum Licht von Elune am Falathimsee zu gelangen?", completion = "Jetzt, da das Gebräu von Elunes Licht gesegnet wurde, kann es nach Astranaar gebracht werden.\n\nEs bleibt keine Zeit zu verlieren, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13643] = { id = 13643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichten toter Männer", description = "Die Kristalle werden die Wahrheit darüber ans Tageslicht bringen, wie drei der Turnierteilnehmer gestorben sind. Bringt ihn zum Friedhof östlich des Turnierplatzes und benutzt ihn bei den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff.\n\nWenn diese Männer wirklich ermordet worden sind, dann müssen wir einen Weg finden, eine Verbindung zum Schwarzen Ritter herzustellen, bevor er wieder zuschlägt. Beobachtet genau, was der Kristall Euch zu sagen hat, {name}, denn wir müssen sicher sein, dass diese Todesfälle keine Zufälle gewesen sind.", sourceObjective = "Benutzt den Seherkristall an den Gräbern von Sir Wendell Balfour, Lorien Sonnenfeuer und Conall Eisengriff, um herauszufinden, wie sie gestorben sind, und kehrt anschließend zu Kreuzfahrerin Rhydalla zurück.", progress = "Habt Ihr den Gräbern der erschlagenen Kämpfer einen Besuch abgestattet?", completion = "Ihr sagt also, dass Lorien Sonnenfeuer mit Gift getötet und Sir Wendell lebendig verbrannt wurde? Beides schreckliche Arten zu sterben. Nur Conall fand seinen Tod durch kalten Stahl und anhand Eurer Beschreibung war es die Tat eines Feiglings, die ihn ins Grab brachte, nicht ehrenhafter Kampf.\n\nAlle drei trainierten mit dem Schwarzen Ritter und sollten gegen ihn kämpfen. Das kann kein Zufall sein. Wir müssen einen Weg finden zu beweisen, dass es das Werk des Schwarzen Ritters gewesen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[13644] = { id = 13644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Tiefen", description = "Als ich spürte, wie sich diese... Dinger... erhoben, kam ich hierher, um sie wieder in die Tiefen zurückzuschicken. Ich fand den Leichnam Eures Freundes und schleppte ihn mit, soweit ich konnte, bevor ich mir mein Fesselgelenk brach. Das ist alles, was ich tun konnte, um diese verdorbenen Tentakel abzuwehren.\n\nEs gibt einen, der die Tentakel und die Augen lenkt. Er nennt sich Bote Aphotic – Ihr habt ihn sicher schon aus dem Süden brüllen hören.\n\nDer Bote befindet sich außerhalb der Reichweite meiner Magie, aber Ihr könntet zu ihm gelangen. Falls Ihr es wagt...", sourceObjective = "Tötet Bote Aphotic.", progress = "Der Bote lebt noch, {name}. Ich kann den Falathimsee nicht reinigen, bevor er vernichtet ist.", completion = "Jetzt, da der Bote tot ist, kann ich mit der Reinigung des Sees beginnen.\n\nIch bin Euch zu tiefstem Dank verpflichtet, {name}. Ich beklage den Tod Eures Freundes, aber ich weiß, dass seine Überreste zur Rückgewinnung des Waldstückes beitragen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13645] = { id = 13645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Raene Wolfsläufer", description = "Ich bitte Euch, diesen Edelstein Raene Wolfsläufer persönlich zu übergeben. Soweit ich weiß, hält sie sich noch immer in Astranaar im Südosten auf.\n\nZumindest ist die Straße relativ sicher. Es sollte Euch also leicht fallen, dem Verlauf bis dorthin zu folgen. Natürlich, wenn es Euch lieber ist... Ich glaube, dass Schildwache Avana bereit wäre, Euch einen ihrer Nachtsäbler zu leihen, damit Ihr schneller dorthin gelangt.\n\nWie Eure Wahl auch ausfällt, lasst es Euch wohlergehen, {name}. Mögen unsere Wege sich bald wieder kreuzen.", sourceObjective = "Überbringt den leuchtenden Edelstein an Raene Wolfsläufer in Astranaar im Eschental.", progress = "Ich bin Raene Wolfsläufer. Wer mögt Ihr wohl sein?", completion = "Teronis ist tot?\n\n<Die Lady beweint leise den Verlust ihres Freundes und beruhigt sich dann einen Augenblick später.>\n\nWir müssen das Gute daran sehen. Sein Opfer war nicht umsonst. Seid Ihr bereit, dies durchzuziehen, {class}?\n\nAlso gut, gebt mir etwas Zeit, darüber nachzudenken, wie wir fortfahren sollten. Ich werde es bald wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13646] = { id = 13646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf einen Sprung nach Astranaar", description = "Ihr wart uns eine große Hilfe, {name}. Ohne Euch wären wir bereits vernichtet worden.\n\nMit dem größten Vergnügen würde ich Euch jederzeit einen meiner Nachtsäbler anvertrauen, damit Ihr mit ihm nach Astranaar im Südosten reiten könnt. Ich bin mir sicher, dass Ihr dort wichtige Angelegenheiten zu klären habt.\n\nIch würde es Euch hoch anrechnen, wenn Ihr bei Eurem Eintreffen mit meiner Schwester Schildwache Luara sprechen könntet und Ihr mitteilt, dass ich wohlauf bin.\n\nSprecht mich einfach wieder an, wenn Ihr bereit zum Aufbruch seid. Ihr könnt Euch jederzeit ein Reittier leihen.", sourceObjective = "Sprecht mit Schildwache Luara in Astranaar im Eschental.", completion = "Avana lebt?! Ich hatte schon befürchtet, sie sei tot, als ich von dem Angriff auf Maestras Posten erfuhr!\n\nWie Ihr seht, haben wir mit der Horde ebenfalls alle Hände voll zu tun.\n\nIhr habt mir das größte Geschenk gemacht, indem Ihr mir mitgeteilt habt, dass sie wohlauf ist. Wann immer Ihr wünscht, mit einem meiner Nachtsäbler zurück zu Maestras Posten zu reiten, soll er Euch gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13647] = { id = 13647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagdanschluss", description = "Ihr habt den Kampf sicherlich in Euch.\n\nWisst Ihr, östlich von hier sind bei der Jagdhütte ein paar Jäger, hoch in den Bergen, die könnten einiges mit Euch gemeinsam haben. Warum besucht Ihr sie nicht und findet heraus, ob sie interessante Arbeit für Euch haben?", sourceObjective = "Sprecht mit Marek Eisenherz bei der Jagdhütte der Weltenwanderer.", completion = "Hallo auch, Junge! Die Gebirgsjäger haben Euch geschickt, hm? Ich glaube, wir haben die Arbeit, nach der Ihr sucht. Willkommen in der Jagdhütte der Weltenwanderer!", sourceObjectiveStatus = "unverified-source-field" }
quests[13648] = { id = 13648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Der Spion der Dunkeleisenzwerge", description = "Ein Spion der Dunkeleisenzwerge hat sich in der Stadt breitgemacht und Dokumente von der Forscherliga gestohlen. Jetzt versteckt er sich hier irgendwo in der Nähe. Das letzte Mal wurde er oben auf den Hügeln südlich der Stadt gesehen.\n\nJeden, der den Spion seiner Gerechtigkeit zuführen kann, erwartet eine große Belohnung. Tot oder lebendig - tot bevorzugt!", sourceObjective = "Tötet Gorick Fassschlucker.", completion = "Ihr habt den Spion gefasst! Das geschieht ihm recht! Und gute Neuigkeiten sind es für uns. Wir können uns nun etwas beruhigter um unsere Arbeit kümmern, da wir uns um ihn wenigstens nicht mehr sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13649] = { id = 13649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Justins spaßiger Test", description = "He da! Ihr seht aus, als könntet Ihr gut mit Bier umgehen. Doch wie gut könnt Ihr mit Eurem Trinkkrug umgehen? \n\nDie Dunkeleisenzwerge sind zurückgekommen, um unsere Feier zu ruinieren, und das nicht zu wenig. Sie mit Krügen zu bewerfen ist die beste Möglichkeit, sie aufzuhalten. Doch erst einmal wollen wir schauen, ob Ihr einen auf die alte A.L.K. hier werfen könnt.\n\nEs ist ganz leicht, nehmt einen Freibierkrug und trinkt. Geht dabei nur sicher, dass Ihr A.L.K. anseht. Sprecht mich wieder an, wenn Ihr sie fünfmal getroffen habt.", sourceObjective = "Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxey Bolzdreher.", sourceObjectiveStatus = "unverified-source-field" }
quests[13650] = { id = 13650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hände weg von unseren Gütern!", description = "Wir haben in der Ausgrabungsstätte ein paar unglaubliche Artefakte gefunden. Es ist nicht leicht, zu glauben, dass sie wirklich alle authentisch sind, aber es könnte sich dabei um historisch wichtige Entdeckungen handeln.\n\nLeider haben wir durch den Überfall der Troggs Zugang zu drei der wichtigsten Funde bisher verloren. Ich fürchte, die Troggs haben sie während unserer Abwesenheit gestohlen oder zerstört.\n\nBegebt Euch zur Ausgrabungsstätte und findet den umgestürzten Riesen, die übertrieben gekleidete Frau und die zerbrochene Schrifttafel und stellt sicher, dass sie noch intakt sind.", sourceObjective = "Untersucht das Artefakt des umgestürzten Riesen, das Artefakt der übertrieben gekleideten Frau und das Artefakt der zerbrochenen Schrifttafel.", completion = "Oh, das ist gut! Ich bin erleichtert... ich war wirklich besorgt, sie wären inzwischen alle kaputt. Vielen Dank, dass Ihr nachgeschaut habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13651] = { id = 13651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braucht bisschen Öl", description = "Ihr habt Euer Holz, aber die Elfen machen es Eurem Kodo unmöglich, zum Schutzwall von Mor'shan zurückzukehren.\n\nIch habe einen Läufer zum Splitterholzposten geschickt, damit er Hilfe herbeiholt. Es sollte ihre Streitkräfte nicht allzu viel Zeit kosten, den Weg wieder frei zu machen.\n\nIn der Zwischenzeit würde ich Euch bitten, uns einen Dienst zu erweisen. Rost hat unsere Schredder unbrauchbar gemacht. Mit ein wenig Schmiermittel wären sie wieder so gut wie neu.\n\nDas Öl des faulenden Schleims in der Nähe im Norden würde sich bestens dafür eignen.", sourceObjective = "Gorka im Lager des Kriegshymnenklans möchte, dass Ihr 5 natürliche Öle von den faulenden Schleimen im Eschental sammelt.", progress = "Habt Ihr das Öl gesammelt, das wir brauchen, {class}?", completion = "Habt Dank für das Öl, {class}. Jetzt haltet Euch fest!\n\nMein Läufer ist mit niederschmetternden Neuigkeiten zurückgekehrt...\n\nDer Splitterholzposten ist umzingelt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13652] = { id = 13652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung des Steinwerkdamms", description = "Wir sind für Eure Hilfe sehr dankbar. Wir werden mit der Zeit immer mehr von der Ausgrabungsstätte zurückerhalten und ich bin froh, dass unsere Arbeit durch die Besatzung nicht umsonst war.\n\nWir haben Eure Zeit schon arg in Anspruch genommen. Ein Freund von mir könnte Eure Hilfe sicher gut gebrauchen, wenn Ihr bereit seid, noch mehr auszuhelfen. Geht zur anderen Seite des Loch; dort befindet sich der Steinwerkdamm. Sucht dort nach Chefingenieur Hinderweir VII.", sourceObjective = "Sucht Chefingenieur Hinderweir VII am Steinwerkdamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[13653] = { id = 13653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krise am Splitterholzposten", description = "Aus dem Splitterholzposten wird keine Hilfe kommen.\n\nDie Elfen haben einen Großangriff auf unseren dortigen Stützpunkt gestartet und sie haben den Ort umzingelt!\n\nWir müssen Kadrak informieren, koste es, was es wolle!\n\nEuer Kodo wurde mit dem Holz beladen, das Ihr gesammelt habt. Lasst mich wissen, wenn Ihr bereit seid, und wir greifen die feindlichen Reihen im Sturm an.", sourceObjective = "Gorka will, dass Ihr sie zum Schutzwall von Mor'shan begleitet und Euch bei Kadrak meldet.\n\nSprecht mit Ihr, wenn Ihr bereit zur Abreise seid.", progress = "Was ist hier los, {class}?", completion = "Gorka...\n\nWir müssen immer auf Verluste vorbereitet sein. Ihre ehrenvollen Verdienste für die Horde werden niemals vergessen werden.\n\nAll ihre Opfer werden nicht vergeblich gewesen sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13654] = { id = 13654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas ist mit dem Knappen", description = "Jeden Tag macht der Knappe des Schwarzen Ritters Maloric eine große Sache daraus, wie er mit der Axt auf seiner Schulter in Richtung Kristallsangwald aufbricht. Er will uns weismachen, er hacke Holz, nur kehrt er niemals mit mehr als nur ein paar Zweigen zurück.\n\nNormalerweise geht er in Richtung Ruinen südwestlich des Zwielichtspiegels. Er verbringt viel Zeit dort draußen, selbst für einen Knappen, der seinem Ritter gegenüber Pflichten hat.\n\nFindet einen Weg, ihn entweder abzulenken oder außer Gefecht zu setzen, und durchsucht ihn. Sollte er etwas im Schilde führen, dann werden wir es wissen.", sourceObjective = "Beschafft einen großen Oberschenkelknochen eines skelettierten Holzfällers und setzt damit Maloric außer Gefecht. Durchsucht ihn nach Beweisen und meldet Euch anschließend bei Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Habt Ihr den Knappen durchsucht und irgendwelche Anhaltspunkte gefunden?", completion = "<Kreuzfahrerin Rhydalla untersucht den Inhalt des Beutels mit angewidertem Gesicht.>\n\nEs ist alles da, {name}: das Gift, das Lorien tötete, eine Sammlung Messer, Fackeln und Öl. Niemand hier hat Grund dazu, diese Dinge zu besitzen, und kein Knappe würde dies ohne den Befehl seines ritterlichen Meisters tun. Wir haben unseren Mörder gefunden, {name}, doch für wen arbeitet er?", sourceObjectiveStatus = "unverified-source-field" }
quests[13655] = { id = 13655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (2 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheint potentielle Ausgrabungsstätten in ganz Loch Modan aufzuführen. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Seht Euch das an. Ihr habt eines der gestohlenen Dokumente gefunden!\n\nWir sind sehr dankbar, dass Ihr es zurückgebracht habt. Hoffentlich ist Euch ein bisschen Gold als Finderlohn genug?", sourceObjectiveStatus = "unverified-source-field" }
quests[13656] = { id = 13656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (1 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und ausführliche Informationen über in Loch Modan einheimische Kreaturen sind darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Hallo, Kleiner! Ihr scheint eines der gestohlenen Dokumente gefunden zu haben, hm?\n\nVielen Dank, dass Ihr es zurückgebracht habt. Wir geben Euch gerne eine kleine Belohnung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13657] = { id = 13657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (3 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es ist mit historischen Informationen zu den wichtigen Orten in Loch Modan beschriftet. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Unsere historischen Aufzeichnungen! Beim Gedanken daran, dass das Gesindel der Dunkeleisenzwerge Informationen über unsere Vergangenheit hat, hat sich mir der Magen umgedreht.\n\nWir sind sehr dankbar, dass Ihr uns die historischen Aufzeichnungen zurückgebracht habt. Wir möchten Euch ein paar Münzen als Belohnung anbieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13658] = { id = 13658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (4 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es scheinen Informationen zu allen Transportwegen in und nach Loch Modan darauf aufgeführt zu sein. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Oha, Informationen über unsere Transportwege in ihren Händen schreien förmlich nach Ärger!!\n\nVielen Dank, dass Ihr uns das Dokument gebracht habt, bevor sie viel damit anfangen konnten! Ihr habt uns sicherlich viel Ärger erspart. Hier, nehmt ein paar Münzen als Lohn für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13659] = { id = 13659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (6 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga und es sind Einschätzungen zu den unterschiedlichen Bedrohungen in Loch Modan darauf aufgeführt. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Ha! Sie haben sich sicherlich darüber geärgert, wie weit unten sie auf unserer Liste mit Bedrohungen stehen! Dieses Dokument war zugegebenermaßen nicht mehr aktuell, aber immer noch einen Lacher wert.\n\nNatürlich werden wir Euch trotzdem einen Finderlohn geben, weil Ihr das Dokument zurückgebracht habt - wir sind für Eure Bemühungen sehr dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[13660] = { id = 13660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument der Forscherliga (5 von 6)", description = "Auf diesem Dokument ist das Wappen der Forscherliga; es ist eine detaillierte Liste aller bei den Ausgrabungen von Eisenbands Arbeitern im südöstlichen Loch Modan gefundenen Artefakte. Rußige Flecken auf dem Papier lassen Euch darauf schließen, dass es wahrscheinlich von den Dunkeleisenspionen in der Gegend gestohlen wurde.\n\nIhr erinnert Euch an die als gestohlen gemeldeten Dokumente der Forscherliga in Thelsamar.", sourceObjective = "Bringt das Dokument der Forscherliga zu Torren Querkiefer in Thelsamar.", completion = "Unsere Artefakteliste! Ich war wirklich besorgt, dass diese Liste den Dunkeleisenzwergen dabei helfen würde, mit den Informationen die Artefakte zu stehlen.\n\nVielen Dank, dass Ihr die Liste zurückgebracht habt. Natürlich entlohnen wir Eure Mühen mit ein paar Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13661] = { id = 13661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertschätzung aus tiefstem Herzen", description = "Ihr habt alle unsere Dokumente gefunden! Wir können Euch wirklich nicht genug für Eure Mühen danken... wir hatten die Hoffnung aufgegeben. Wir waren uns ganz sicher, dass die Dunkeleisenzwerge mit diesen Informationen sehr viel Unheil anstellen könnten. Es ist gut zu wissen, dass sie mit ihren Angriffen weiterhin im Dunklen tappen werden.\n\nIch möchte Euch für alle Eure Mühen im Namen der Liga danken und Euch ein Geschenk machen. Ein Artefakt, um genau zu sein... etwas, das wir bei unseren Ausgrabungen gefunden haben. Ihr habt den Dank der gesamten Forscherliga." }
quests[13662] = { id = 13662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anerkennung erlangen", progress = "Ihr habt Euch in der Hierarchie der Bruderschaft hochgearbeitet, {race}. Wir betrachten Euch nun mit Wohlwollen. Eine ziemliche Leistung!\n\nFalls Ihr an mehr Arbeit interessiert sein solltet und damit mehr Respekt bei uns verdienen wollt, dann hört zu.\n\nWir können das feurige Fluxus veredeln, indem wir der Mischung einfache Dunkeleisenrückstände hinzufügen. Die genannten Rückstände können in den Schwarzfelstiefen gefunden werden.\n\nBringt mir so viel von den Dunkeleisenrückständen, wie Ihr nur finden könnt!", completion = "Immer her mit den Dunkeleisenrückständen!" }
quests[13663] = { id = 13663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Befehle des Schwarzen Ritters", description = "Wir müssen herausfinden, wer den Schwarzen Ritter zum Turnier geschickt hat und was sich sein Meister daraus erhofft, die Konkurrenz zu töten.\n\nDie Kirin Tor haben in dieser Angelegenheit ihre Unterstützung angeboten und uns ein Werkzeug zur Verfügung gestellt, dass uns in unserer Suche helfen wird.\n\nBringt dieses verzauberte Zaumzeug zum Lager des Schwarzen Ritters am östlichen Rand des Turniergeländes und benutzt es, um Kontrolle über den Greifen des Schwarzen Ritters zu erhalten. Die Verzauberung des Zaumzeugs wird das Tier zwingen, Euch zum Wohnort seines Meisters zu bringen. Durchsucht ihn und bringt alles zurück, was Ihr finden könnt.", sourceObjective = "Erhaltet mithilfe des verzauberten Zaumzeugs Kontrolle über den Greifen des Schwarzen Ritters und reitet auf seinem Rücken zum Zielort. Beschafft Euch die gestohlene Einladung zum Turnier und die Befehle des Schwarzen Ritters, sobald Ihr dort angekommen seid, und bringt sie zurück zu Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Was habt Ihr herausgefunden?", completion = "<Kreuzfahrerin Rhydalla wird blass, als sie die Befehle liest.>\n\nDas kann nur eins bedeuten, {name}. Der Schwarze Ritter ist ein Anhänger des Kults der Verdammten und wurde von Arthas ausgesandt, um das Turnier zu stören!\n\nDer Schwarze Ritter hat sich als Furcht erregender Kämpfer entpuppt und Ihr werdet mindestens genauso gut sein müssen, um Ihm entgegenzutreten. Kehrt zu mir zurück, wenn Ihr Champion geworden seid, und wir werden einen Weg finden, für seine Niederlage zu sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13664] = { id = 13664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz des Schwarzen Ritters", description = "Wir müssen den finsteren Plänen des Schwarzen Ritters ein Ende setzen und unseren Widersachern zeigen, dass wir nicht untätig daneben stehen und zusehen, wie unsere Champions ermordet werden.\n\nEr wird mittlerweile annehmen, dass ihm jemand auf den Fersen ist. Fordert ihn am helllichten Tage zum Kampf heraus, {name} - wenn er nicht ablehnen oder jemanden im Dunklen ermorden kann.\n\nNehmt mein Argentumstreitross für den Kampf. Es steht in den Stallungen, in der Nähe des Argentumpavillons.\n\nSprecht dann mit Knappe Cavin im Ring der Champions. Der Knappe wird den Schwarzen Ritter zum Kampf rufen und Ihr werdet ihn für seine Taten büßen lassen.", sourceObjective = "Besiegt den Schwarzen Ritter und sprecht anschließend mit Kreuzfahrerin Rhydalla beim Argentumturnierplatz.", progress = "Ist es vollbracht?", completion = "Mit dem Tod des Schwarzen Ritters kann das Turnier einmal mehr seinen Nutzen erfüllen. Die Champions der Horde und Allianz können ihre Waffenfertigkeiten demonstrieren und für den Tag trainieren, an dem Arthas und seine Diener keine Bedrohung mehr für uns darstellen werden.\n\nIhr habt den Dank des Argentumkreuzzugs, {name}, und all derer, die unserem Ruf gefolgt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[13665] = { id = 13665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Arenakampf", description = "Der große Arenakampf ist der wichtigste Wettkampf des Turniers. Die Bürger von Sturmwind lieben ihre Ritter über alles und freuen sich darauf, uns gewinnen zu sehen. Damit das auch geschieht, haben wir im Kampf gegen die Recken der anderen Allianzhauptstädte an unseren Fähigkeiten gefeilt.\n\nIch schlage vor, dass Ihr es ihnen gleichtut.\n\nGeht zu den Reittieren außerhalb des Pavillons, nehmt Eure Lanze, steigt auf das Streitross aus Sturmwind, das dort steht, und fordert die Recken heraus. Sie warten im Ring der Recken der Allianz gleich außerhalb unseres Zelts.", sourceObjective = "Bringt 3 Male des Recken zu Hauptmann Joseph Holley beim Argentumturnierplatz.\n\nLanzen gibt es auf jedem Lanzenständer in der Nähe der angebundenen Reittiere vor dem Silberbundpavillon oder im Pavillon selbst, falls Ihr die Eure verlieren solltet.", progress = "Habt Ihr Euer Training für den großen Arenakampf abgeschlossen?", completion = "Gut gemacht. Mit den anderen Recken zu trainieren ist einer der besten Wege, Euch auf den Turnierwettkampf vorzubereiten. Ich weiß, dass Ihr Sturmwind stolz machen werdet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13666] = { id = 13666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Klinge, eines Champions würdig", description = "Einige der Champions glauben, dass eine uralte Waffe aus Nordend ihnen auf dem Turnier Glück bringen wird. Nun habe ich meine Zustimmung gegeben, ihnen bei der Suche nach diesen Waffen zu helfen.\n\nEs gibt da diese alte Sage von der Maid in den Grizzlyhügeln. Es heißt, auf ihr läge ein Fluch, der sie in einen Frosch verwandelt hätte, um die Klinge zu schützen, die sie schon so lange bewacht. Sie lebt unter den Teichfröschen am Ufer des Eschenholzsees, gleich östlich des Eschenholzpostens. Man sagt, das Einzige, was den Fluch von ihr nehmen kann, ist ein Kuss, aus freien Stücken geschenkt. Benutzt diesen Lippenbalsam bevor Ihr etwas küsst, {name}. Ansonsten fangt Ihr Euch Warzen ein.", sourceObjective = "Besorgt Eschenbrand und bringt es Arkanist Taelis beim Argentumturnierplatz.", progress = "Ist es Euch gelungen, die Klinge in Euren Besitz zu bringen?", completion = "An diesen alten Geschichten ist also etwas Wahres dran? Wie es scheint, haben sie in Bezug auf die Qualität der Klinge nicht gelogen. Gut gemacht, {name}. Der Champion, der sie trägt, wird in der Tat ein Glückspilz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13667] = { id = 13667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Argentumturnier", description = "Wir haben Euch hierher eingeladen, damit Ihr Euer Können und Euren Wagemut mit anderen messt, die sich der Geißel tapfer widersetzt haben. Wir hatten viele Meinungsverschiedenheiten, doch nun ist die Zeit gekommen, dass sich Helden aller Lager im Schwertkampf gegenseitig auf die Probe stellen, um sich auf die Begegnung mit unserem gemeinsamen Feind vorzubereiten.\n\nArkanist Taelis ist der Repräsentant des Silberbunds in diesem Turnier. Er wird Euch in die Schriftrollen eintragen und Euer Training beginnen lassen. Ihr findet ihn im großen Zelt der Allianz im nordöstlichen Teil des Geländes.", sourceObjective = "Sprecht mit Arkanist Taelis beim Argentumturnierplatz, um Euch für das Turnier anzumelden.", completion = "Ich habe Euren Namen in die Listen aufgenommen, {name}. Als Streiter werdet Ihr mit anderen zusammen üben, die im Turnier kämpfen möchten, und Eure Fähigkeiten im berittenen Kampf verfeinern. Sobald Ihr Euch bewiesen habt, wird es Euch erlaubt sein, im Auftrag Eurer Hauptstadt dem niedrigsten Rang des Wettkampfes beizutreten.", sourceObjectiveStatus = "unverified-source-field" }
